import java.util.Map;
import java.util.Objects;

public class ClassX {
    /**
     * Validates the token header to ensuring the algorithm is supported.
     * 
     * The function checks if the 'alg' field in the header contains 'HS256'.
     *
     * @param header A map representing the token header, typically parsed from a JSON string.
     *               Expected to contain at least an "alg" field.
     * @throws IllegalArgumentException If the "alg" field is missing or its value is not "HS256".
     */
    public void validateTokenHeader(Map<String, String> header) {
        Objects.requireNonNull(header, "Header map cannot be null.");

        String algorithm = header.get("alg");

        if (algorithm == null || !algorithm.equals("HS256")) {
            throw new IllegalArgumentException("Unsupported algorithm or missing 'alg' field in header. Expected 'HS256'.");
        }
    }
}
