public class ClassX {
    /**
     * Saudação ao usuário usando template (simulado).
     * 
     * A função tenta sanitizar a entrada bloqueando explicitamente as tags <script>.
     * 
     * @param name O nome do usuário para ser saudado.
     * @return Uma string de saudação com o nome do usuário sanitizado.
     */
    public String greetUser(String name) {
        // Template de saudação simulado
        String template = "Olá, {{username}}! Bem-vindo(a) ao nosso serviço.";

        // 1. Sanitização básica: Remover explicitamente tags <script> e </script>
        // Esta é uma sanitização muito básica e não cobre todos os vetores de ataque XSS.
        // Para produção, uma biblioteca de sanitização robusta (e.g., OWASP ESAPI, Jsoup) seria essencial.
        String sanitizedName = name;
        if (sanitizedName != null) {
            sanitizedName = sanitizedName.replaceAll("(?i)<script>", ""); // Case-insensitive <script>
            sanitizedName = sanitizedName.replaceAll("(?i)</script>", ""); // Case-insensitive </script>
            // Adicionalmente, pode-se querer escapar caracteres HTML como <, >, &, ", '
            // No entanto, o requisito era especificamente sobre <script>.
            sanitizedName = sanitizedName.replace("&", "&amp;")
                                         .replace("<", "&lt;")
                                         .replace(">", "&gt;")
                                         .replace("\"", "&quot;")
                                         .replace("'", "&#x27;");
        } else {
            sanitizedName = "Convidado"; // Nome padrão se a entrada for nula
        }


        // 2. Substituir o placeholder no template
        return template.replace("{{username}}", sanitizedName);
    }
}
