import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Saudação ao usuário usando template (simulado).
     * 
     * A função tenta sanitizar a entrada bloqueando explicitamente as tags <script>.
     *
     * @param userName O nome do usuário a ser saudado.
     * @return Uma string de saudação com o nome do usuário sanitizado.
     */
    public String greetUserSanitized(String userName) {
        if (userName == null || userName.trim().isEmpty()) {
            userName = "Usuário Anônimo";
        }

        // Sanitização básica: Remover explicitamente as tags <script> (case-insensitive)
        // e seus conteúdos. Uma solução real precisaria de uma biblioteca de sanitização robusta.
        String sanitizedName = userName;
        Pattern scriptPattern = Pattern.compile("<script.*?>.*?</script>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = scriptPattern.matcher(sanitizedName);
        if (matcher.find()) {
            sanitizedName = matcher.replaceAll("");
        }

        // Uma sanitização adicional para evitar injeção básica fora de tags <script>
        // seria escapar caracteres HTML como '<', '>', '&', '"', "'"
        sanitizedName = sanitizedName.replace("&", "&amp;")
                                     .replace("<", "&lt;")
                                     .replace(">", "&gt;")
                                     .replace("\"", "&quot;")
                                     .replace("'", "&#x27;"); // Apostrophe

        // Simulando um template de saudação
        return String.format("Olá, %s! Bem-vindo ao nosso sistema.", sanitizedName.trim());
    }

    /**
     * Exemplo de uso.
     */
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        String name1 = "Alice";
        System.out.println(classX.greetUserSanitized(name1));

