     * 
     * @param memberName Çıkarılacak üyenin adı.
     * @return Başlangıç eğik çizgileri temizlenmiş üye adı (simüle edilmiş kullanım için).
     */
    public String extractMember(String memberName) {
        if (memberName == null) {
            System.out.println("Hata: Üye adı null olamaz.");
            return null;
        }

        String cleanedMemberName = memberName;

        // Mutlak yolları önlemek için üye adının bir eğik çizgi ile başlayıp başlamadığını kontrol edin.
        // Hem Unix/Linux tarzı eğik çizgi hem de Windows tarzı ters eğik çizgi kontrol edilir.
        if (memberName.startsWith("/") || memberName.startsWith("\\")) {
            System.out.println("Uyarı: Üye adı '" + memberName + "' bir eğik çizgi ile başlıyor. Güvenlik için başlangıç eğik çizgisi kaldırılıyor.");
            cleanedMemberName = memberName.substring(1);
        }

        System.out.println("Simülasyon: Arşivden '" + cleanedMemberName + "' üyesi çıkarılıyor.");

        // Gerçek bir uygulamada, burada dosya yazma veya başka işlemler yapılırdı.
        // Şimdilik sadece simülasyon mesajı ve temizlenmiş adı döndürüyoruz.
        return cleanedMemberName;
    }

    // Örnek kullanım için bir main metodu
    public static void main(String[] args) {
        ClassX archiver = new ClassX();

        System.out.println("--- Durum 1: Normal üye adı ---");
        archiver.extractMember("dosya/resim.jpg");

        System.out.println("\n--- Durum 2: Başında eğik çizgi olan üye adı ---");
