        archiver.extractMember("\\Windows\\System32\\driver.sys");

        System.out.println("\n--- Durum 4: Boş üye adı ---");
        archiver.extractMember("");

        System.out.println("\n--- Durum 5: Null üye adı ---");
        archiver.extractMember(null);
    }
}
