     * @param zipFilePath The path to the zip archive.
     * @param destDirectory The directory where the archive contents will be extracted.
     * @throws IOException If an I/O error occurs during extraction.
     * @throws SecurityException If a path traversal attempt is detected.
     */
    public void extractZip(String zipFilePath, String destDirectory) throws IOException, SecurityException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // iterates over entries in the zip file
            while (entry != null) {
                String entryName = entry.getName();

                // Prevent path traversal
                if (entryName.contains("..") || entryName.contains(":/") || entryName.startsWith("/")) {
