                }

                File filePath = new File(destDirectory + File.separator + entryName);

                if (!filePath.getCanonicalPath().startsWith(destDir.getCanonicalPath() + File.separator)) {
                    throw new SecurityException("Attempted path traversal detected for entry: " + entryName);
                }

                if (!entry.isDirectory()) {
                    // if the entry is a file, extract it
                    extractFile(zipIn, filePath);
                } else {
                    // if the entry is a directory, make sure the directory exists
                    filePath.mkdirs();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }

    /**
     * Extracts a file from the zip input stream to the specified destination file.
     *
