import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Purkaa zip-arkisto määritettyyn kohteeseen tarkistamalla jäsenpolut.
     * 
     * Toiminto käy läpi arkiston jäsenet ja yrittää estää polun kulkemisen tarkistamalla, sisältääkö jäsenen nimi '..'.
     * 
     * @param zipFilePath Polku purettavaan zip-tiedostoon.
     * @param destDirectory Polku hakemistoon, johon sisältö puretaan.
     * @throws IOException Jos I/O-virhe tapahtuu purkamisen aikana.
     * @throws SecurityException Jos zip-tiedosto sisältää potentiaalisen polun kulkemisen ('..').
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException, SecurityException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdir();
        }

        byte[] buffer = new byte[1024];
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            while (zipEntry != null) {
                String fileName = zipEntry.getName();
                File newFile = new File(destDir, fileName);

                // Polun kulkemisen (path traversal) tarkistus
                // Estää tiedostojen purkamisen kohdehakemiston ulkopuolelle.
                String canonicalDestinationPath = destDir.getCanonicalPath();
                String canonicalExtractionPath = newFile.getCanonicalPath();

                if (!canonicalExtractionPath.startsWith(canonicalDestinationPath + File.separator)) {
                    // Tämä tarkistus estää, että tiedostoa puretaan toiseen levypartitioon tai
                    // alihakemistojen ulkopuolelle.
                    // Lisäksi, jos tiedostonimessä on '..', se muuttuu `getCanonicalPath()`-kutussa.
                    // Esim. `destDir/../foo.txt` -> `/foo.txt` (kun `destDir` on `/tmp/dest`).
                    // Tällöin `canonicalExtractionPath` ei enää alkaisi `canonicalDestinationPath + File.separator`-merkkijonolla.
                    throw new SecurityException("Zip entry is trying to escape the destination directory: " + fileName);
                }

                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Failed to create directory " + newFile);
                    }
                } else {
                    // Varmista, että vanhempien hakemistot luodaan, jos niitä ei ole olemassa
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Failed to create directory " + parent);
                    }

                    // Kirjoita tiedoston sisältö
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
            zis.closeEntry();
        }
    }
}
