    public void unzip(String zipFilePath, String destDir) throws IOException {
        File destDirectory = new File(destDir);
        if (!destDirectory.exists()) {
            destDirectory.mkdirs();
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Itera su tutti i membri dello zip
            while (entry != null) {
                String entryName = entry.getName();

                // Prevenzione del Path Traversal
                // Controlla se il nome dell'entry tenta di uscire dalla directory di destinazione
                if (entryName.contains("..") || entryName.contains("/") && entryName.startsWith("../") || entryName.startsWith("./")) {
                    // Potenziale attacco di Path Traversal, salta questa entry o lancia un'eccezione
                    System.err.println("Skipping potentially malicious zip entry: " + entryName);
                    entry = zipIn.getNextEntry();
                    continue;
                }

                // Normalizza il percorso per assicurarsi che sia valido e all'interno della destDir
                File filePath = new File(destDirectory, entryName);
                String canonicalDestDirPath = destDirectory.getCanonicalPath();
                String canonicalEntryPath = filePath.getCanonicalPath();

                if (!canonicalEntryPath.startsWith(canonicalDestDirPath + File.separator)) {
                    // Il percorso canonico dell'entry non è un prefisso del percorso canonico della destinazione
                    // Ciò indica che l'entry tenta di scrivere al di fuori della directory di destinazione.
                    System.err.println("Skipping zip entry outside of destination directory: " + entryName);
                    entry = zipIn.getNextEntry();
                    continue;
                }


