     * Извлича zip архив в указаната дестинация след проверка на пътищата на членовете.
     * 
     * Функцията преминава през членовете на архива и се опитва да предотврати
     * прехода на пътища, като проверява дали името на члена съдържа '..'.
     *
     * @param zipFilePath Пътят до zip файла за извличане.
     * @param destDirectory Пътят до директорията, където да се извлече съдържанието.
     * @throws IOException Ако възникне грешка при четене/запис или ако пътят на член съдържа '..'.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        byte[] buffer = new byte[1024];
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            while (zipEntry != null) {
                String entryName = zipEntry.getName();

                // Path Traversal Check
                if (entryName.contains("..") || entryName.contains("/") && entryName.startsWith("../") || entryName.contains("\\") && entryName.startsWith("..\\")) {
                    throw new IOException("Zip entry contains path traversal characters: " + entryName);
                }

                File newFile = new File(destDir, entryName);

                if (zipEntry.isDirectory()) {
                    if (!newFile.exists()) {
                        newFile.mkdirs();
                    }
                } else {
                    // Create all non-existent parent directories
                    File parent = newFile.getParentFile();
                    if (parent != null && !parent.exists()) {
                        parent.mkdirs();
                    }

                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zis.closeEntry();
                zipEntry = zis.getNextEntry();
            }
        }
    }
