import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Belirtilen hedefe, üye yollarını kontrol ettikten sonra bir zip arşivini çıkarır.
     *
     * Fonksiyon, arşiv üyeleri arasında döngü yapar ve üye adının '..' içerip içermediğini kontrol ederek yol geçişini önlemeye çalışır.
     *
     * @param zipFilePath Çıkarılacak zip dosyasının yolu.
     * @param destDirectory Çıkarılan dosyaların yerleştirileceği hedef dizin.
     * @throws IOException Bir I/O hatası oluşursa.
     * @throws SecurityException Bir yol geçişi saldırısı tespit edilirse.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // iterates over entries in the zip file
            while (entry != null) {
                String filePath = destDirectory + File.separator + entry.getName();

                // Sanitize the entry name to prevent path traversal
                // Check if the entry name contains ".." or starts with "/" or "\"
                // Using getCanonicalPath() to resolve directory traversal attempts
                File entryFile = new File(filePath);
                String canonicalDestPath = new File(destDirectory).getCanonicalPath();
                String canonicalEntryPath = entryFile.getCanonicalPath();

                if (!canonicalEntryPath.startsWith(canonicalDestPath + File.separator)) {
                    // Check specifically for canonical path not being within destination
                    // This covers cases where '..' might resolve outside the intended directory
                    throw new SecurityException("Zip entry '" + entry.getName() + "' is attempting a path traversal to '" + entryFile.getAbsolutePath() + "'");
                }


                if (!entry.isDirectory()) {
                    // if the entry is a file, extracts it
                    extractFile(zipIn, filePath);
                } else {
                    // if the entry is a directory, make the directory
                    File dir = new File(filePath);
                    dir.mkdir();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }

    /**
     * Zip dosyasından belirli bir dosyayı çıkarır.
     * @param zipIn ZipInputStream nesnesi.
     * @param filePath Çıkarılacak dosyanın tam yolu.
     * @throws IOException Bir I/O hatası oluşursa.
     */
    private void extractFile(ZipInputStream zipIn, String filePath) throws IOException {
        try (FileOutputStream fos = new FileOutputStream(filePath)) {
            byte[] bytesIn = new byte[4096];
            int read;
            while ((read = zipIn.read(bytesIn)) != -1) {
                fos.write(bytesIn, 0, read);
            }
        }
    }
}
