                // Path Traversal Vulnerability Prevention:
                // Check if the entry name contains '..' to prevent directory traversal
                if (entryName.contains("..") || entryName.contains("/") && entryName.startsWith("../")) {
                    System.err.println("Skipping potentially malicious entry: " + entryName);
                    entry = zipIn.getNextEntry();
                    continue;
                }

                File filePath = new File(destDir, entryName);

                if (!filePath.getCanonicalPath().startsWith(destDir.getCanonicalPath() + File.separator)) {
                    throw new IOException("Entry is outside of the target directory: " + entryName);
                }

                if (!entry.isDirectory()) {
                    // if the entry is a file, extract it
                    extractFile(zipIn, filePath);
                } else {
                    // if the entry is a directory, create it
                    filePath.mkdirs();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
