    /**
     * Nag-eextract ng zip archive sa tinukoy na destinasyon pagkatapos suriin ang mga landas ng miyembro.
     * 
     * Ang function ay nag-iikot sa mga miyembro ng archive at sinusubukang pigilan ang path traversal sa pamamagitan ng pagsuri kung ang pangalan ng miyembro ay naglalaman ng '..'.
     * @param zipFilePath Ang path ng zip file na i-eextract.
     * @param destDirectory Ang direktoryo kung saan ilalagay ang mga na-extract na file.
     * @throws IOException Kung may error sa I/O habang nag-eextract, kabilang ang mga pagtatangka ng path traversal.
     */
    public void extractZip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdir();
        }

        byte[] buffer = new byte[1024]; // Buffer para sa pagbasa ng mga file

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
