                // o kung ito ay isang absolute path (nagsisimula sa '/' o '\').
                if (fileName.contains("..") || fileName.startsWith("/") || fileName.startsWith("\\")) {
                    throw new IOException("Zip entry contains path traversal attempt: " + fileName);
                }

                File newFile = new File(destDir, fileName);

                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Nabigo ang paglikha ng direktoryo: " + newFile);
                    }
                } else {
                    // Siguraduhin na nilikha ang parent directories
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Nabigo ang paglikha ng parent directory: " + parent);
                    }

                    // Isulat ang nilalaman ng file
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
        } // try-with-resources ay awtomatikong magsasara ng ZipInputStream
    }
}
