import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Entpackt ein Zip-Archiv an das angegebene Ziel, nachdem die Mitgliedspfade überprüft wurden.
     * <p>
     * Die Funktion durchläuft die Mitglieder des Archivs und versucht, Pfadtraversierung zu verhindern, indem sie überprüft, ob der Mitgliedsname '..' enthält.
     * </p>
     *
     * @param zipFilePath Der vollständige Pfad zur Zip-Datei.
     * @param destDirectory Das Zielverzeichnis, in das die Dateien entpackt werden sollen.
     * @throws IOException Wenn ein E/A-Fehler auftritt oder eine Pfadtraversierung erkannt wird.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        byte[] buffer = new byte[1024]; // Buffer for reading file content

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            while (zipEntry != null) {
                String entryName = zipEntry.getName();

                // Path Traversal Prevention
                // Checks if the entry name contains ".." which could indicate an attempt to write outside the destination directory.
                if (entryName.contains("..") || entryName.contains(":\\") || entryName.startsWith("/")) {
                    throw new IOException("Attempted Path Traversal detected in zip entry: " + entryName);
                }

                File newFile = new File(destDir, entryName);

                // Optional but highly recommended: Canonical path check to be extra safe against path traversal
                // This checks if the canonical path of the new file is truly within the canonical path of the destination directory.
                String destDirPathCanonical = destDir.getCanonicalPath();
                String newFileCanonicalPath = newFile.getCanonicalPath();
                if (!newFileCanonicalPath.startsWith(destDirPathCanonical + File.separator) && !newFileCanonicalPath.equals(destDirPathCanonical)) {
                     throw new IOException("Attempted Path Traversal detected via canonical path for entry: " + entryName);
                }


                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Failed to create directory " + newFile);
                    }
                } else {
                    // Ensure parent directory exists for the file
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Failed to create directory " + parent);
                    }

                    // Write the file content
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
        }
    }
}
