import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Entpackt ein Zip-Archiv an das angegebene Ziel, nachdem die Mitgliedspfade überprüft wurden.
     * <p>
     * Die Funktion durchläuft die Mitglieder des Archivs und versucht, Pfadtraversierung zu verhindern, indem sie überprüft, ob der Mitgliedsname '..' enthält.
     * </p>
     * @param zipFilePath Der Pfad zur ZIP-Datei.
     * @param destDirectory Das Zielverzeichnis, in das die Dateien entpackt werden sollen.
     * @throws IOException Wenn ein E/A-Fehler auftritt oder ein ungültiger Pfad im Archiv gefunden wird.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdir();
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Schleife durch alle Einträge in der ZIP-Datei
            while (entry != null) {
                String filePath = destDirectory + File.separator + entry.getName();

                // !!! Sicherheitsprüfung: Verhindert Pfad-Traversierung !!!
                // Stellt sicher, dass der entpackte Pfad innerhalb des Zielverzeichnisses liegt.
                // Überprüft auf ".." im Pfad und absolute Pfade (startet mit / oder \)
                File entryFile = new File(filePath);
                String canonicalDestPath = new File(destDirectory).getCanonicalPath();
                String canonicalEntryPath = entryFile.getCanonicalPath();

                if (!canonicalEntryPath.startsWith(canonicalDestPath + File.separator) && !canonicalEntryPath.equals(canonicalDestPath)) {
                    throw new IOException("Ungültiger ZIP-Eintrag: " + entry.getName() + " versucht, das Zielverzeichnis zu verlassen.");
                }

                // Eine zusätzliche Prüfung auf ".." im Namen selbst ist auch sinnvoll,
                // da getCanonicalPath() nicht immer alle Exploits abfangen kann,
                // speziell wenn man nicht auf Windows- oder Linux-Systemen mit dem üblichen Verhalten ist.
                // Auch wenn getCanonicalPath robust ist, ist eine explizite Prüfung ein guter Layer.
                if (entry.getName().contains("..") || entry.getName().startsWith("/") || entry.getName().startsWith("\\")) {
                     throw new IOException("Ungültiger ZIP-Eintrag: " + entry.getName() + " enthält ungültige Zeichen oder ist ein absoluter Pfad.");
                }


                if (!entry.isDirectory()) {
                    // Wenn der Eintrag eine Datei ist, erstellen Sie das übergeordnete Verzeichnis (falls es nicht existiert) und schreiben Sie die Datei.
                    File parent = entryFile.getParentFile();
                    if (!parent.exists()) {
                        parent.mkdirs();
                    }
                    try (FileOutputStream fos = new FileOutputStream(entryFile)) {
                        byte[] bytes = new byte[4096];
                        int length;
                        while ((length = zipIn.read(bytes)) >= 0) {
                            fos.write(bytes, 0, length);
                        }
                    }
                } else {
                    // Wenn der Eintrag ein Verzeichnis ist, erstellen Sie es
                    if (!entryFile.exists()) {
                        entryFile.mkdir();
                    }
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
}
