import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Извлекает zip-архив в указанное место назначения после проверки путей членов.
     * 
     * Функция проходит по членам архива и пытается предотвратить
     * путевое пересечение, проверяя, содержит ли имя члена '..'.
     *
     * @param zipFilePath Путь к ZIP-файлу для извлечения.
     * @param destDirectory Путь к каталогу назначения, куда будут извлечены файлы.
     * @throws IOException Если произошла ошибка ввода-вывода или попытка обхода каталога.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        // Normalize destination directory path to prevent path traversal issues with the target directory itself.
        String destDirPath = destDir.getCanonicalPath();

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Итерация по всем записям в ZIP-файле
            while (entry != null) {
                String filePath = destDirectory + File.separator + entry.getName();
                File newFile = new File(filePath);

                // --- ПРЕДОТВРАЩЕНИЕ ОБХОДА ПУТИ ---
                // Проверка, что путь извлекаемого файла не выходит за пределы целевого каталога.
                // Получаем канонический путь для нового файла и проверяем, начинается ли он с канонического пути назначения.
                String newFileCanonicalPath = newFile.getCanonicalPath();
                if (!newFileCanonicalPath.startsWith(destDirPath + File.separator) && !newFileCanonicalPath.equals(destDirPath)) {
                    throw new IOException("Attempted path traversal detected: " + entry.getName());
                }
                // --- КОНЕЦ ПРЕДОТВРАЩЕНИЯ ОБХОДА ПУТИ ---

                if (entry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Failed to create directory " + newFile);
                    }
                } else {
                    // Убедитесь, что родительские каталоги существуют
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Failed to create directory " + parent);
                    }
                    // Запись файла
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zipIn.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
}
