                // Дополнительная (но менее надежная) проверка на '..' в имени, если canonicalPath недоступен или для быстрой отсечки
                if (entry.getName().contains("..")) {
                     throw new IOException("Attempted Path Traversal (contains '..') during ZIP extraction for file: " + entry.getName());
                }


                if (!entry.isDirectory()) {
                    // Если это файл, убедимся, что родительские каталоги существуют
                    File parent = newFile.getParentFile();
                    if (!parent.exists()) {
                        parent.mkdirs();
                    }
                    // Записываем файл
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zipIn.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                } else {
                    // Если это каталог, создаем его
                    newFile.mkdir();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
}
