     * @throws SecurityException Si une tentative de traversée de chemin est détectée.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException, SecurityException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
