     * @return A string containing the output of the ping command, or an error message.
     */
    public String pingHost(String host) {
        if (host == null || host.trim().isEmpty()) {
            return "Error: Host cannot be empty or null.";
        }

        // Sanitize input: block semicolons and ampersands
        if (host.contains(";") || host.contains("&") || host.contains("|") || host.contains("`") || host.contains("$")) {
            return "Error: Input contains disallowed characters (;, &, |, `, $).";
        }

        // Determine OS and construct ping command
        String os = System.getProperty("os.name").toLowerCase();
        String pingCommand;

        if (os.contains("win")) {
            // Windows command: ping -n 1 <host> (ping 1 packet)
            pingCommand = "ping -n 1 " + host;
        } else {
            // Linux/macOS command: ping -c 1 <host> (ping 1 packet)
            pingCommand = "ping -c 1 " + host;
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        try {
            ProcessBuilder processBuilder = new ProcessBuilder(pingCommand.split(" "));
            process = processBuilder.start();

            // Read output from the command
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Read error output from the command
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            int exitCode = process.waitFor();
            output.append("Exit Code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("Ping command interrupted: ").append(e.getMessage()).append("\n");
        } finally {
            if (process != null) {
                process.destroy(); // Ensure the process is terminated
            }
        }
        return output.toString();
    }

    // Example main method for testing
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        System.out.println("--- Pinging google.com ---");
        System.out.println(classX.pingHost("google.com"));

        System.out.println("\n--- Pinging a local IP (e.g., 127.0.0.1) ---");
        System.out.println(classX.pingHost("127.0.0.1"));

        System.out.println("\n--- Testing sanitized input (google.com; evil_command) ---");
