                    output.append("ERROR: ").append(line).append("\n"); // Prefix error lines for clarity
                }
            }

            // Wait for the process to complete and get its exit code
            int exitCode = process.waitFor();
            output.append("Ping command exited with code: ").append(exitCode).append("\n");

        } finally {
            // Ensure the process resources are released.
            // In most cases, reading all streams and calling waitFor() is sufficient.
            if (process != null) {
                process.destroy(); // Optional: forcefully terminate the process if still running
            }
        }

        return output.toString();
