public class ClassX {
    /**
     * Pings a specified host.
     *
     * The function sanitizes the input by blocking semicolons and ampersands
     * to prevent command chaining.
     *
     * @param host The host to ping.
     * @return A string containing the output of the ping command, or an error message.
     */
    public static String pingHost(String host) {
        if (host == null || host.trim().isEmpty()) {
            return "Error: Host cannot be empty.";
        }

        // Sanitize input: Block semicolons, ampersands, and other common command injection characters.
        // Also blocking pipes (|), backticks (`), dollar signs ($), parentheses, and spaces for stricter security.
        // While spaces are part of valid hostnames, blocking them here forces a single token, preventing easy
        // command splitting without more sophisticated parsing (which the user shouldn't be able to do).
        if (host.contains(";") || host.contains("&") || host.contains("|") ||
            host.contains("`") || host.contains("$") || host.contains("(") ||
            host.contains(")") || host.contains(">") || host.contains("<") ||
            host.contains(" ") || host.contains("`")) { // Duplicate ` for emphasis, can be removed.
            return "Error: Invalid characters detected in host name. Semicolons, ampersands, pipes, " +
                   "and other command-chaining characters or spaces are not allowed.";
        }

        // Determine ping command based on OS (basic check)
        String osName = System.getProperty("os.name").toLowerCase();
        List<String> command = new ArrayList<>();

        if (osName.contains("win")) {
            // Windows command: ping -n 4 <host>
            command.add("ping");
            command.add("-n");
            command.add("4");
            command.add(host);
        } else {
            // Linux/macOS command: ping -c 4 <host>
            command.add("ping");
            command.add("-c");
            command.add("4");
            command.add(host);
        }

        StringBuilder output = new StringBuilder();
        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true); // Combine stdout and stderr

        try {
            Process process = processBuilder.start();

            // Read output from the command
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append(System.lineSeparator());
                }
            }

            int exitCode = process.waitFor(); // Wait for the process to complete

            if (exitCode != 0) {
                // Ping failed (e.g., host unreachable, unknown host)
                // The output will contain the error message from ping itself.
                return "Ping command exited with code " + exitCode + ":\n" + output.toString();
            }

        } catch (IOException e) {
            return "Error executing ping command: " + e.getMessage();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            return "Ping command was interrupted: " + e.getMessage();
        }

        return output.toString();
    }

    public static void main(String[] args) {
        System.out.println("--- Pinging Valid Host (Google) ---");
        System.out.println(pingHost("google.com"));

        System.out.println("\n--- Pinging Invalid Host (Empty) ---");
        System.out.println(pingHost(""));

        System.out.println("\n--- Pinging Invalid Host (Semicolon) ---");
        System.out.println(pingHost("google.com;ls"));

        System.out.println("\n--- Pinging Invalid Host (Ampersand) ---");
        System.out.println(pingHost("google.com&ls"));

        System.out.println("\n--- Pinging Invalid Host (Pipe) ---");
        System.out.println(pingHost("google.com|ls"));

        System.out.println("\n--- Pinging Non-Existent Host ---");
        // This should return output from ping indicating host not found.
        System.out.println(pingHost("thisisnotavalidhostnamenonexistent123.com"));
    }
}
