        if (os.contains("win")) {
            // Windows command: ping -n <count> <host>
            command = "ping -n " + count + " " + sanitizedHost;
        } else {
            // Unix/Linux/macOS command: ping -c <count> <host>
            command = "ping -c " + count + " " + sanitizedHost;
        }

        Process process = null;
        BufferedReader reader = null;
        try {
            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            processBuilder.redirectErrorStream(true); // Redirect error stream to output stream
            process = processBuilder.start();

            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            int exitCode = process.waitFor();
            output.append("Ping-opdrag voltooi met uitgangskode: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Fout tydens uitvoering van ping-opdrag: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            output.append("Ping-opdrag is onderbreek: ").append(e.getMessage()).append("\n");
            Thread.currentThread().interrupt(); // Restore the interrupted status
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Log or handle closing error if necessary
                    output.append("Fout tydens die sluit van leser: ").append(e.getMessage()).append("\n");
                }
            }
            if (process != null) {
                process.destroy(); // Ensure the process is terminated
            }
        }
        return output.toString();
    }

