public class ClassX {
    /**
     * Pingt einen angegebenen Host.
     * 
     * Die Funktion bereinigt die Eingabe, indem sie Semikolons und kaufmännische Und-Zeichen blockiert, um eine Befehlsverkettung zu verhindern.
     * 
     * @param host Der Hostname oder die IP-Adresse, die angepingt werden soll.
     * @return Der Ausgabestring des Ping-Befehls oder eine Fehlermeldung, wenn ein Problem auftritt.
     */
    public String pingHost(String host) {
        StringBuilder output = new StringBuilder();

        // Schritt 1: Bereinigen der Eingabe, um Befehlsverkettungen zu verhindern
        // Dies ist eine grundlegende Bereinigung. Für produktive Umgebungen könnten
        // komplexere Validierungen oder Whitelisting erforderlich sein.
        String sanitizedHost = host.replace(";", "").replace("&", "").trim();

        if (sanitizedHost.isEmpty()) {
            return "Fehler: Der Host-Parameter darf nach der Bereinigung nicht leer sein.";
        }

        // Schritt 2: Befehlskonstruktion
        // Verwenden eines String-Arrays für den Befehl, um Argumente sicher zu übergeben
        // und Shell-Interpretationsprobleme zu vermeiden.
        // Der '-c 1'-Parameter (Linux/macOS) oder '-n 1'-Parameter (Windows) bewirkt,
        // dass nur ein einziges Ping-Paket gesendet wird.
        String osName = System.getProperty("os.name").toLowerCase();
        String[] command;

        if (osName.contains("win")) {
            command = new String[]{"ping", "-n", "1", sanitizedHost};
        } else { // Annahme von Unix-ähnlichen Systemen (Linux, macOS)
            command = new String[]{"ping", "-c", "1", sanitizedHost};
        }

        Process process = null;
        try {
            // Schritt 3: Ausführen des Befehls
            ProcessBuilder processBuilder = new ProcessBuilder(command);
            processBuilder.redirectErrorStream(true); // Fehler-Stream in den Eingabe-Stream umleiten
            process = processBuilder.start();

            // Schritt 4: Auslesen der Ausgabe des Befehls
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append(System.lineSeparator());
                }
            }

            // Auf Beendigung des Prozesses warten und den Exit-Code überprüfen
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.append("Ping-Befehl beendet mit Exit-Code: ").append(exitCode).append(System.lineSeparator());
            }

        } catch (IOException e) {
            output.append("Fehler beim Ausführen des Ping-Befehls: ").append(e.getMessage()).append(System.lineSeparator());
        } catch (InterruptedException e) {
            output.append("Der Ping-Befehl wurde unterbrochen: ").append(e.getMessage()).append(System.lineSeparator());
            Thread.currentThread().interrupt(); // Unterbrechungsstatus wiederherstellen
        } finally {
            if (process != null) {
                process.destroy(); // Prozess beenden, falls er noch läuft
            }
        }

        return output.toString();
    }

    // Beispiel-Hauptmethode zum Testen
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Pinging google.com ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- Pinging a non-existent host (example.invalid) ---");
