        System.out.println("\n--- Pinging 127.0.0.1 ---");
        System.out.println(pinger.pingHost("127.0.0.1"));

        System.out.println("\n--- Pinging with empty host ---");
        System.out.println(pinger.pingHost(""));
    }
}
