import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Pings määratud hosti.
     * 
     * Funktsioon puhastab sisendi, blokeerides semikoolonid ja ampersandid, et vältida käsu ahelat.
     *
     * @param host The host to ping.
     * @return The output of the ping command, or an error message if the command fails.
     */
    public String pingHost(String host) {
        // Input sanitization: Block semicolons and ampersands to prevent command chaining.
        // This regex replaces any occurrence of ';' or '&' with an empty string.
        String sanitizedHost = host.replaceAll("[;&]", "");

        // Determine the appropriate ping command based on the operating system
        String osName = System.getProperty("os.name").toLowerCase();
        String command;
        if (osName.contains("win")) {
            // For Windows: ping -n 1 <host> (ping once)
            command = "ping -n 1 " + sanitizedHost;
        } else {
            // For Unix-like systems (Linux, macOS): ping -c 1 <host> (ping once)
            command = "ping -c 1 " + sanitizedHost;
        }

        StringBuilder output = new StringBuilder();
        Process process;
        try {
            // Execute the ping command
            process = Runtime.getRuntime().exec(command);

            // Read the standard output from the command
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append("\n");
                }
            }

            // Read the error output from the command (if any)
            try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                String line;
                while ((line = errorReader.readLine()) != null) {
                    // Prepend "ERROR: " to distinguish error output
                    output.append("ERROR: ").append(line).append("\n");
                }
            }

            // Wait for the process to complete and get its exit value
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.append("Ping command exited with code ").append(exitCode).append(".\n");
            }

        } catch (IOException e) {
            // Handle errors related to command execution (e.g., command not found)
            return "Error executing ping command: " + e.getMessage();
        } catch (InterruptedException e) {
            // Handle cases where the current thread is interrupted while waiting for the process
            Thread.currentThread().interrupt(); // Restore the interrupted status
            return "Ping command interrupted: " + e.getMessage();
        }

        return output.toString();
    }
}
