            int exitCode = process.waitFor();
            System.out.println("\nPing käsu väljumiskood: " + exitCode);

        } catch (IOException e) {
            System.err.println("Viga ping käsu käivitamisel: " + e.getMessage());
        } catch (InterruptedException e) {
            System.err.println("Ping käsu täitmine katkestati: " + e.getMessage());
