        // Remove common command injection characters like semicolon (;) and ampersand (&).
        // Using replaceAll with a regex ensures any occurrences are removed.
        String sanitizedHost = host.replaceAll("[;&|<>`$()]", ""); // Also include pipe, redirection, backticks, dollar, parentheses for better safety

        if (sanitizedHost.trim().isEmpty()) {
            return "Erro: O host especificado é inválido após a sanitização.";
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;
        BufferedReader errorReader = null;

        try {
            // 2. Determine OS and construct the ping command.
            String osName = System.getProperty("os.name").toLowerCase();
            String[] command;

            if (osName.contains("win")) {
                // Windows command: ping -n 1 <host>
                command = new String[]{"cmd.exe", "/c", "ping", "-n", "1", sanitizedHost};
            } else {
                // Unix/Linux/macOS command: ping -c 1 <host>
                command = new String[]{"ping", "-c", "1", sanitizedHost};
            }

            // 3. Execute the command.
            ProcessBuilder processBuilder = new ProcessBuilder(command);
            processBuilder.redirectErrorStream(true); // Redirect error stream to input stream
            process = processBuilder.start();

            // 4. Read the output of the command.
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // 5. Wait for the process to complete and check its exit value.
            // Add a timeout to prevent hanging indefinitely.
            boolean finished = process.waitFor(10, TimeUnit.SECONDS);

            if (!finished) {
                process.destroy(); // Terminate the process if it times out
                return "Erro: O comando ping excedeu o tempo limite.\n" + output.toString();
            }

            int exitCode = process.exitValue();
            if (exitCode != 0) {
                // Append any error messages if the command failed, even if redirectErrorStream(true) was used
                // Sometimes, specific errors might still be useful to discern.
                output.append("Erro: O comando ping terminou com o código de saída ").append(exitCode).append(".\n");
            }

        } catch (IOException e) {
            output.append("Erro de I/O ao executar o comando ping: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("Erro: O processo ping foi interrompido: ").append(e.getMessage()).append("\n");
        } finally {
            // 6. Close the resources.
            try {
                if (reader != null) {
                    reader.close();
                }
                if (errorReader != null) {
                    errorReader.close(); // This might not be needed if error stream is redirected
                }
            } catch (IOException e) {
                // Log or handle closing error if necessary
                output.append("Erro ao fechar os leitores: ").append(e.getMessage()).append("\n");
            }
            if (process != null) {
                process.destroyForcibly(); // Ensure the process is terminated
            }
        }

        return output.toString();
