    public String pingHost(String host) {
        if (host == null || host.trim().isEmpty()) {
            return "Erro: O host não pode ser nulo ou vazio.";
        }

        // 1. Sanitize the input to prevent command injection
        // Remove ';' and '&' characters from the host string.
        // A more robust solution would validate the host against a regex for valid hostnames/IPs.
        String sanitizedHost = host.replaceAll("[;&]", "");

        // Trim again in case only illegal characters were provided or leading/trailing spaces were left after sanitization
        sanitizedHost = sanitizedHost.trim();

        if (sanitizedHost.isEmpty()) {
            return "Erro: O host sanitizado está vazio. Verifique a entrada.";
        }

        StringBuilder output = new StringBuilder();
        try {
            // Determine the ping command based on the OS
            List<String> command = new ArrayList<>();
            String osName = System.getProperty("os.name").toLowerCase();

            if (osName.contains("win")) {
                // For Windows, use "ping -n 4 <host>"
                command.add("ping");
                command.add("-n");
                command.add("4"); // Send 4 packets
                command.add(sanitizedHost);
            } else {
                // For Linux/macOS, use "ping -c 4 <host>"
                command.add("ping");
                command.add("-c");
                command.add("4"); // Send 4 packets
                command.add(sanitizedHost);
            }

            ProcessBuilder processBuilder = new ProcessBuilder(command);
            // Redirect error stream to output stream so we can read both from one stream
            processBuilder.redirectErrorStream(true);

            Process process = processBuilder.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.insert(0, "Aviso: O comando ping retornou com código de saída " + exitCode + ".\n");
            }

        } catch (IOException e) {
            output.append("Erro de E/S ao executar o comando ping: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            output.append("Erro: O comando ping foi interrompido: ").append(e.getMessage()).append("\n");
            Thread.currentThread().interrupt(); // Restore the interrupted status
        }

        return output.toString();
    }

