     * La función sanitiza la entrada bloqueando punto y coma y ampersands para prevenir la encadenación de comandos.
     * 
     * @param host La dirección IP o nombre de host a hacer ping.
     * @return El resultado del comando ping como una cadena, o un mensaje de error si falla.
     */
    public String pingHost(String host) {
        // Sanitize the input to prevent command injection
        // Remove characters commonly used for command chaining: ;, &, &&, ||, |
        String sanitizedHost = host.replaceAll("[;&|]", "");

        if (sanitizedHost.trim().isEmpty()) {
            return "Error: Host no especificado o inválido después de la sanitización.";
        }

        StringBuilder output = new StringBuilder();
        Process p;
        try {
            // Determine the OS to use the correct ping command
            String osName = System.getProperty("os.name").toLowerCase();
            ProcessBuilder processBuilder;

            if (osName.contains("win")) {
                // For Windows: ping -n 1 <host>
                processBuilder = new ProcessBuilder("cmd.exe", "/c", "ping", "-n", "1", sanitizedHost);
            } else {
                // For Unix-like systems (Linux, macOS): ping -c 1 <host>
                processBuilder = new ProcessBuilder("ping", "-c", "1", sanitizedHost);
            }

            p = processBuilder.start();
            p.waitFor(); // Wait for the command to complete

            BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Also capture error stream in case of issues
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(p.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

        } catch (IOException e) {
            output.append("Error al ejecutar el comando ping: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("El comando ping fue interrumpido: ").append(e.getMessage()).append("\n");
        }

        if (output.length() == 0) {
            return "No se recibió ninguna salida del comando ping. Verifique el host o los permisos.";
