        String osName = System.getProperty("os.name").toLowerCase();
        String command;
        if (osName.contains("win")) {
            // Windows: ping -n <count> <host>
            command = "ping -n 4 " + sanitizedHostname;
        } else {
            // Linux/macOS: ping -c <count> <host>
            command = "ping -c 4 " + sanitizedHostname;
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;
        BufferedReader errorReader = null;

        try {
            // Exécuter la commande ping.
            process = Runtime.getRuntime().exec(command);

            // Lire la sortie standard.
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Lire la sortie d'erreur standard (si des erreurs se produisent).
            errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            // Attendre la fin du processus et obtenir le code de sortie.
            int exitCode = process.waitFor();
            output.append("Exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Exception d'E/S lors de l'exécution de la commande: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            output.append("Le processus ping a été interrompu: ").append(e.getMessage()).append("\n");
