        } finally {
            try {
                if (reader != null) reader.close();
                if (errorReader != null) errorReader.close();
            } catch (IOException e) {
                output.append("Erreur lors de la fermeture des lecteurs: ").append(e.getMessage()).append("\n");
            }
            if (process != null) {
                process.destroy(); // Assurer que le processus est terminé
            }
        }
        return output.toString();
    }

