    public String pingHost(String host) {
        // Почистване на входа: премахване на точки и амперсанди
        // Това е примитивна защита и не е изчерпателна срещу всички видове инжекции.
        String cleanedHost = host.replaceAll("[.&]", ""); 

        if (cleanedHost.isEmpty()) {
            return "Грешка: Невалиден или празен хост след почистване.";
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            // Изпълнение на ping командата
            // Забележка: Синтаксисът на ping командата може да варира между ОС (Windows/Linux/macOS)
            // Пример за Linux/macOS: "ping -c 4 " + cleanedHost
            // Пример за Windows: "ping -n 4 " + cleanedHost
            // Използваме универсален подход, който често работи, но е добре да се знае за разликите.
            String osName = System.getProperty("os.name").toLowerCase();
            String command;
            if (osName.contains("win")) {
                command = "ping -n 1 " + cleanedHost; // -n 1 за 1 пакет на Windows
            } else {
                command = "ping -c 1 " + cleanedHost; // -c 1 за 1 пакет на Linux/macOS
            }

            process = Runtime.getRuntime().exec(command);

            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Четене на евентуални грешки
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("Грешка (stderr): ").append(line).append("\n");
            }
            errorReader.close();

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.append("Командата завърши с код на изход: ").append(exitCode).append("\n");
            }

        } catch (IOException e) {
            output.append("Възникна IOException: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Възстановяване на прекъсвания статус
            output.append("Възникна InterruptedException: ").append(e.getMessage()).append("\n");
        } finally {
            try {
                if (reader != null) {
                    reader.close();
                }
                if (process != null) {
                    process.destroy(); // Освобождаване на системните ресурси
                }
            } catch (IOException e) {
                output.append("Грешка при затваряне на ресурси: ").append(e.getMessage()).append("\n");
            }
        }

        return output.toString();
    }

