        ClassX pinger = new ClassX();

        System.out.println("--- Тест 1: Валиден хост (Google) ---");
        String result1 = pinger.pingHost("google.com");
        System.out.println(result1);

        System.out.println("\n--- Тест 2: Хост с невалидни символи (почистват се) ---");
        // Очаква се "googlecom" да бъде пингнат
