        System.out.println(result2);

        System.out.println("\n--- Тест 3: Локален хост (127.0.0.1) ---");
        String result3 = pinger.pingHost("127.0.0.1");
        System.out.println(result3);

        System.out.println("\n--- Тест 4: Несъществуващ хост ---");
