    /**
     * Fetches content from a generated URL after validating the host.
     * 
     * This function sanitizes the host by checking for invalid characters like spaces.
     *
     * @param host The host part of the URL (e.g., "example.com").
     * @param path The path part of the URL (e.g., "/api/data").
     * @return The content fetched from the URL as a String.
     * @throws IllegalArgumentException If the host is null, empty, or contains invalid characters like spaces.
     * @throws MalformedURLException If the constructed URL is not a valid URL.
     * @throws IOException If an I/O error occurs while opening the connection or reading from it.
     */
    public String fetchContentFromValidatedHost(String host, String path) throws MalformedURLException, IOException {
        // 1. Host validation and sanitization
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }
        if (host.contains(" ")) {
            throw new IllegalArgumentException("Host contains invalid characters (spaces).");
        }
        // Trim host to remove any legitimate leading/trailing whitespace if present
        String sanitizedHost = host.trim();

        // 2. Path preparation
        // Ensure path starts with '/' and is not null/empty to form a valid URL
        String actualPath = (path == null || path.isEmpty()) ? "/" : path;
        if (!actualPath.startsWith("/")) {
            actualPath = "/" + actualPath;
        }

        // 3. Construct the URL. Using HTTPS for secure communication by default.
        URL url = new URL("https", sanitizedHost, actualPath);

        // 4. Fetch content from the URL
        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n"); // Append newline to preserve original line breaks
            }
        }
        // Remove the last newline character if it exists to prevent an extra blank line
        if (content.length() > 0 && content.charAt(content.length() - 1) == '\n') {
            content.setLength(content.length() - 1);
        }

        return content.toString();
    }
}
