    /**
     * Mengambil konten dari URL yang dihasilkan setelah memvalidasi host.
     *
     * Fungsi ini membersihkan host dengan memeriksa karakter tidak valid seperti spasi.
     *
     * @param urlString URL yang akan diambil kontennya.
     * @return Konten dari URL sebagai String.
     * @throws MalformedURLException Jika URL tidak valid atau memiliki format yang salah.
     * @throws IllegalArgumentException Jika host URL mengandung karakter tidak valid.
     * @throws IOException Jika terjadi kesalahan saat membuka koneksi atau membaca konten dari URL.
     */
    public String getContentFromValidatedUrl(String urlString) throws MalformedURLException, IllegalArgumentException, IOException {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new IllegalArgumentException("URL string cannot be null or empty.");
        }

        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("Invalid URL format: " + urlString + " - " + e.getMessage());
        }

        String host = url.getHost();
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("URL host cannot be null or empty.");
        }

        // Regular expression to check for invalid characters in a hostname.
        // Valid characters for a hostname typically include alphanumeric characters, hyphens, and dots.
        // This pattern checks for anything that is NOT a letter, digit, hyphen, or dot.
        // It effectively catches spaces and most other special characters.
        Pattern invalidHostCharPattern = Pattern.compile("[^a-zA-Z0-9.-]");
        Matcher matcher = invalidHostCharPattern.matcher(host);

        if (matcher.find()) {
            throw new IllegalArgumentException("URL host '" + host + "' contains invalid characters. Detected: '" + matcher.group() + "'");
        }

        // Proceed to fetch content if host is valid
        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append(System.lineSeparator());
            }
        }
        return content.toString();
    }
}
