import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URLConnection;

public class ClassX {
    /**
     * 在验证主机后，从生成的 URL 获取内容。
     * 
     * 此函数通过检查空格等无效字符来清理主机。
     *
     * @param host 待验证和从中获取内容的主机字符串。这可以是域名、IP地址或完整的URL。
     * @return URL 的内容字符串。
     * @throws IllegalArgumentException 如果主机字符串无效或无法清理，或者无法形成有效的URL。
     * @throws IOException 如果在尝试连接到URL或读取其内容时发生I/O错误。
     */
    public String getContentFromValidatedHost(String host) throws IllegalArgumentException, IOException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }

        // 1. 清理主机：检查空格等无效字符
        String cleanedHost = host.trim();

        // 简单的清理：如果主机名中包含空格，则认为其无效
        if (cleanedHost.contains(" ")) {
            throw new IllegalArgumentException("Host contains invalid characters (spaces): " + host);
        }

        // 2. 验证并构建 URL
        URL url;
        try {
            // 如果主机不以协议（如http://或https://）开头，则默认添加 http://
            if (!cleanedHost.startsWith("http://") && !cleanedHost.startsWith("https://")) {
                cleanedHost = "http://" + cleanedHost;
            }
            url = new URL(cleanedHost);
        } catch (MalformedURLException e) {
            // 如果主机格式不正确，无法创建有效的URL，则抛出异常
            throw new IllegalArgumentException("Invalid host format, cannot form a URL: " + cleanedHost, e);
        }

        // 3. 获取 URL 内容
        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // 可以设置连接超时和读取超时，以避免长时间等待
            connection.setConnectTimeout(5000); // 5秒连接超时
            connection.setReadTimeout(10000);   // 10秒读取超时

            // 使用 BufferedReader 从 InputStream 读取内容
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append("\n"); // 每行末尾添加换行符
                }
            }
        } catch (IOException e) {
            // 捕获并重新抛出I/O异常，提供更多上下文信息
            throw new IOException("Failed to retrieve content from URL: " + url.toString(), e);
        }

        return content.toString();
    }
}
