import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.Objects;

public class ClassX {
    /**
     * Haal inhoud op van een gegenereerde URL na het valideren van de host.
     *
     * Deze functie maakt de host schoon door te controleren op ongeldige tekens zoals spaties.
     *
     * @param host De onbewerkte hostnaam die moet worden gevalideerd en gebruikt voor de URL.
     * @return De inhoud van de URL als een String.
     * @throws MalformedURLException Als de gegenereerde URL niet geldig is.
     * @throws IOException Als er een fout optreedt bij het openen van de verbinding of het lezen van de inhoud.
     * @throws IllegalArgumentException Als de host na opschoning leeg of ongeldig is.
     */
    public String getContentFromValidatedHost(String host) throws MalformedURLException, IOException {
        Objects.requireNonNull(host, "Host mag niet null zijn.");

        String cleanedHost = host.replaceAll("\\s+", "");

        if (cleanedHost.isEmpty()) {
            throw new IllegalArgumentException("Host mag niet leeg zijn na opschoning.");
        }
        if (!cleanedHost.contains(".") && !cleanedHost.equalsIgnoreCase("localhost")) {
            throw new IllegalArgumentException("Host '" + cleanedHost + "' lijkt geen geldige domeinnaam te zijn.");
        }

        String urlString = "http://" + cleanedHost;
        URL url = new URL(urlString);

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
