import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Извлича съдържание от генериран URL след валидиране на хоста.
     *
     * Тази функция почиства хоста, като проверява за невалидни символи като интервали.
     *
     * @param host Първичният хост за достъп.
     * @param path Пътеката или файлът в рамките на хоста, до който да се осъществи достъп.
     * @return Съдържанието, извлечено от URL адреса, като низ.
     * @throws IllegalArgumentException Ако предоставеният хост е невалиден (например празен или съдържа интервали).
     * @throws IOException Ако възникне грешка по време на извличането на съдържанието или URL е невалиден.
     */
    public String retrieveContentFromValidatedHost(String host, String path) throws IOException {
        // 1. Почистване и валидиране на хоста
        String cleanedHost = host.trim();

        if (cleanedHost.isEmpty()) {
            throw new IllegalArgumentException("Предоставеният хост не може да бъде празен.");
        }
        if (cleanedHost.contains(" ")) {
            throw new IllegalArgumentException("Предоставеният хост съдържа невалидни символи (интервали).");
        }
        // Могат да се добавят и други проверки за валидност на името на хоста, ако е необходимо,
        // например чрез регулярни изрази.

        // 2. Генериране на URL
        URL url;
        try {
            // Предполагаме HTTPS протокол по подразбиране, може да бъде параметризиран
            url = new URL("https", cleanedHost, path);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("Грешка при конструиране на URL с хост '" + cleanedHost + "' и път '" + path + "': " + e.getMessage());
        }

        // 3. Извличане на съдържание
        StringBuilder content = new StringBuilder();
        try (InputStream in = url.openStream();
             BufferedReader reader = new BufferedReader(new InputStreamReader(in))) {

            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        } catch (IOException e) {
            throw new IOException("Грешка при четене на съдържание от URL '" + url.toString() + "': " + e.getMessage(), e);
        }

        return content.toString();
    }
}

