import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URLConnection;

public class ClassX {
    /**
     * Obtiene contenido de una URL generada después de validar el host.
     *
     * Esta función sanitiza el host al verificar la presencia de caracteres inválidos como espacios.
     *
     * @param host El nombre de host a validar y usar.
     * @param path La ruta del recurso en el host.
     * @return El contenido de la URL como una cadena.
     * @throws IllegalArgumentException Si el host contiene caracteres inválidos.
     * @throws IOException Si ocurre un error al conectar o leer de la URL.
     */
    public String getContentFromValidatedUrl(String host, String path) throws IOException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("El host no puede ser nulo o vacío.");
        }

        // Sanitización del host: verificar la presencia de caracteres inválidos como espacios.
        // Una validación más robusta podría usar expresiones regulares.
        if (host.contains(" ") || host.contains("\t") || host.contains("\n") || host.contains("\r")) {
            throw new IllegalArgumentException("El host contiene caracteres de espacio inválidos.");
        }

        URL url;
        try {
            // Se asume un protocolo HTTPS por defecto. Se puede parametrizar si es necesario.
            url = new URL("https", host, path);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("URL mal formada después de la validación del host: " + e.getMessage());
        }

        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // Opcional: configurar timeouts para la conexión y lectura
            connection.setConnectTimeout(5000); // 5 segundos para establecer la conexión
            connection.setReadTimeout(10000);   // 10 segundos para leer datos

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append("\n");
                }
            }
        } catch (IOException e) {
            throw new IOException("Error al leer contenido de la URL " + url.toString() + ": " + e.getMessage(), e);
        }

        return content.toString();
    }
}
