public class ClassX {
    /**
     * Получает содержимое с сгенерированного URL после проверки хоста.
     * 
     * Эта функция очищает хост, проверяя наличие недопустимых символов, таких как пробелы.
     * @param host Хост, который будет использован для создания URL.
     * @param path Путь, который будет добавлен к URL.
     * @return Содержимое, полученное по URL, или null в случае ошибки.
     */
    public String getContent(String host, String path) {
        // Очистка хоста: удаляем пробелы.
        // Для более строгой валидации можно использовать регулярные выражения,
        // но для указанной проблемы "пробелы" достаточно replace().
        String cleanedHost = host.replace(" ", "");

        URL url = null;
        try {
            // Протокол по умолчанию - http
            url = new URL("http", cleanedHost, path);
        } catch (MalformedURLException e) {
            System.err.println("Malformed URL encountered: " + e.getMessage());
            return null;
        }

        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // Установка таймаутов для соединения и чтения, чтобы избежать зависаний
            connection.setConnectTimeout(5000); // 5 секунд на установление соединения
            connection.setReadTimeout(10000);   // 10 секунд на чтение данных

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append("\n");
                }
            }
        } catch (IOException e) {
            System.err.println("Error reading content from URL " + url.toString() + ": " + e.getMessage());
            return null;
        }

        return content.toString();
    }
}
