import java.util.regex.Pattern;

public class ClassX {

    /**
     * Retrieves content from a URL generated after validating the host.
     *
     * This function sanitizes the host by checking for invalid characters such as spaces.
     * It extracts the host from the provided URL string and validates it before
     * attempting to open a connection and read its content.
     *
     * @param urlString The URL string from which to retrieve content.
     * @return The content of the URL as a String.
     * @throws IllegalArgumentException If the provided URL string is malformed or its host contains invalid characters.
     * @throws IOException If an I/O error occurs while opening the connection or reading from the URL.
     */
    public String retrieveContentFromValidatedHostUrl(String urlString) throws IOException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid URL format: " + urlString, e);
        }

        String host = url.getHost();

        // Validate the host for invalid characters, specifically spaces as mentioned in the javadoc.
        // A more comprehensive validation might check for other characters not allowed in hostnames.
        // RFC 1123, 3.1: Host names are sequences of labels separated by dots.
        // Labels must start and end with an alphanumeric character (a-z, A-Z, 0-9).
        // Interior characters can be alphanumeric or hyphens.
        // Length of labels must be between 1 and 63. Total hostname length must not exceed 255.
        // For simplicity, we are checking for spaces as explicitly requested.
        // This regex pattern allows letters, digits, hyphens, and dots, but disallows leading/trailing hyphens on labels
        // and ensures no spaces are present.
        Pattern hostPattern = Pattern.compile("^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$");
        Matcher matcher = hostPattern.matcher(host);

        if (host.contains(" ") || !matcher.matches()) {
            throw new IllegalArgumentException("Invalid characters found in host: " + host);
        }

        StringBuilder content = new StringBuilder();
        URLConnection connection = url.openConnection();
        connection.setConnectTimeout(5000); // 5 seconds connect timeout
        connection.setReadTimeout(10000);   // 10 seconds read timeout

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
