     * @throws IllegalArgumentException Se l'host dell'URL contiene caratteri non validi (es. spazi)
     *                                  o se l'URL non ha un host valido.
     * @throws IOException Se si verifica un errore durante la connessione o la lettura dal URL.
     */
    public String retrieveContentFromURL(String urlString) throws MalformedURLException, IOException {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new IllegalArgumentException("URL string cannot be null or empty.");
        }

        // 1. Parse the URL string
        URL url = new URL(urlString);

        // 2. Extract and validate the host
        String host = url.getHost();

        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("URL does not contain a valid host: " + urlString);
        }

        // Specific validation for invalid characters like spaces as per Javadoc
        if (host.contains(" ")) {
            throw new IllegalArgumentException("URL host contains invalid characters (e.g., spaces): " + host);
        }

        // Additional host validation could be added here, e.g., using a regex for valid hostname characters,
        // but for now, we strictly follow the "invalid characters like spaces" requirement.

        // 3. Retrieve content if host is valid
        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // Set reasonable timeouts to prevent hanging indefinitely
            connection.setConnectTimeout(5000); // 5 seconds
            connection.setReadTimeout(5000);    // 5 seconds

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append(System.lineSeparator());
                }
            }
        } catch (IOException e) {
            // Wrap or re-throw as appropriate for the application context
            throw new IOException("Failed to retrieve content from URL: " + urlString + ". Error: " + e.getMessage(), e);
        }

        return content.toString();
    }
}
