import java.net.URL;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.net.MalformedURLException;

public class ClassX {
    /**
     * Ανακτά περιεχόμενο από μια παραγόμενη διεύθυνση URL μετά την επικύρωση του κεντρικού υπολογιστή.
     *
     * Αυτή η λειτουργία καθαρίζει τον κεντρικό υπολογιστή ελέγχοντας για μη έγκυρους χαρακτήρες όπως κενά.
     *
     * @param scheme Το πρωτόκολλο της διεύθυνσης URL (π.χ., "http", "https").
     * @param host Το όνομα κεντρικού υπολογιστή που πρέπει να επικυρωθεί και να χρησιμοποιηθεί.
     * @param path Το μονοπάτι της διεύθυνσης URL (π.χ., "/api/data").
     * @return Το περιεχόμενο που ανακτήθηκε από τη διεύθυνση URL ως String, ή null αν προκύψει σφάλμα.
     * @throws IllegalArgumentException Εάν ο παρεχόμενος κεντρικός υπολογιστής περιέχει μη έγκυρους χαρακτήρες.
     */
    public String retrieveContentFromValidatedUrl(String scheme, String host, String path) {
        // Καθαρισμός και επικύρωση του κεντρικού υπολογιστή
        String cleanedHost = cleanAndValidateHost(host);

        try {
            // Δημιουργία της πλήρους διεύθυνσης URL
            URL url = new URL(scheme, cleanedHost, path);

            // Ανάκτηση περιεχομένου
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
                StringBuilder content = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line);
                }
                return content.toString();
            }
        } catch (MalformedURLException e) {
            System.err.println("Σφάλμα: Η διεύθυνση URL είναι λανθασμένη: " + e.getMessage());
            return null;
        } catch (IOException e) {
            System.err.println("Σφάλμα: Αποτυχία ανάκτησης περιεχομένου από τη διεύθυνση URL: " + e.getMessage());
            return null;
        }
    }

    /**
     * Καθαρίζει και επικυρώνει ένα όνομα κεντρικού υπολογιστή.
     * Ελέγχει για μη έγκυρους χαρακτήρες όπως κενά και ρίχνει εξαίρεση εάν βρεθούν.
     *
     * @param host Το όνομα κεντρικού υπολογιστή προς καθαρισμό και επικύρωση.
     * @return Το καθαρισμένο όνομα κεντρικού υπολογιστή.
     * @throws IllegalArgumentException Εάν ο παρεχόμενος κεντρικός υπολογιστής περιέχει μη έγκυρους χαρακτήρες.
     */
    private String cleanAndValidateHost(String host) {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Ο κεντρικός υπολογιστής δεν μπορεί να είναι κενός.");
        }

        // Έλεγχος για μη έγκυρους χαρακτήρες, όπως κενά
        if (host.matches(".*\\s+.*")) {
            throw new IllegalArgumentException("Ο κεντρικός υπολογιστής περιέχει μη έγκυρους χαρακτήρες (π.χ. κενά): " + host);
        }

        // Περαιτέρω επικύρωση μπορεί να προστεθεί εδώ (π.χ. έλεγχος για έγκυρα μοτίβα ονόματος τομέα)
        // Για παράδειγμα, μπορεί να χρησιμοποιηθεί μια πιο αυστηρή regex
        // `if (!host.matches("^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$"))`

        // Απλά επιστρέφουμε τον καθαρισμένο (χωρίς επικεφαλής/τελικά κενά) κεντρικό υπολογιστή
        // αφού έχουμε ήδη ελέγξει για εσωτερικά κενά.
        return host.trim();
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // Παράδειγμα επιτυχούς χρήσης
        System.out.println("--- Επιτυχημένο Παράδειγμα ---");
        String content1 = classX.retrieveContentFromValidatedUrl("https", "jsonplaceholder.typicode.com", "/todos/1");
        if (content1 != null) {
            System.out.println("Περιεχόμενο ανακτήθηκε: " + content1.substring(0, Math.min(content1.length(), 100)) + "...");
        } else {
            System.out.println("Αποτυχία ανάκτησης περιεχομένου.");
        }
        System.out.println("\n");

        // Παράδειγμα με μη έγκυρο κεντρικό υπολογιστή (με κενά)
        System.out.println("--- Παράδειγμα με μη έγκυρο κεντρικό υπολογιστή (κενά) ---");
        try {
            String content2 = classX.retrieveContentFromValidatedUrl("http", "invalid host with spaces.com", "/");
            if (content2 != null) {
                System.out.println("Περιεχόμενο ανακτήθηκε: " + content2);
            }
        } catch (IllegalArgumentException e) {
            System.err.println("Αναμενόμενο σφάλμα: " + e.getMessage());
        }
        System.out.println("\n");

        // Παράδειγμα με κενό κεντρικό υπολογιστή
        System.out.println("--- Παράδειγμα με κενό κεντρικό υπολογιστή ---");
        try {
            String content3 = classX.retrieveContentFromValidatedUrl("http", "", "/");
            if (content3 != null) {
                System.out.println("Περιεχόμενο ανακτήθηκε: " + content3);
            }
        } catch (IllegalArgumentException e) {
            System.err.println("Αναμενόμενο σφάλμα: " + e.getMessage());
        }
        System.out.println("\n");

        // Παράδειγμα με null κεντρικό υπολογιστή
        System.out.println("--- Παράδειγμα με null κεντρικό υπολογιστή ---");
        try {
            String content4 = classX.retrieveContentFromValidatedUrl("http", null, "/");
            if (content4 != null) {
                System.out.println("Περιεχόμενο ανακτήθηκε: " + content4);
            }
        } catch (IllegalArgumentException e) {
            System.err.println("Αναμενόμενο σφάλμα: " + e.getMessage());
        }
        System.out.println("\n");

        // Παράδειγμα με μη έγκυρο πρωτόκολλο (δεν είναι σφάλμα επικύρωσης κεντρικού υπολογιστή, αλλά MalformedURLException)
        System.out.println("--- Παράδειγμα με μη έγκυρο πρωτόκολλο ---");
        String content5 = classX.retrieveContentFromValidatedUrl("ftp://", "example.com", "/");
        if (content5 == null) {
            System.out.println("Αναμενόμενη αποτυχία λόγω MalformedURLException.");
        }
        System.out.println("\n");
    }
}
