public class ClassX {
    /**
     * Ανακτά περιεχόμενο από μια παραγόμενη διεύθυνση URL μετά την επικύρωση του κεντρικού υπολογιστή.
     *
     * Αυτή η λειτουργία καθαρίζει τον κεντρικό υπολογιστή ελέγχοντας για μη έγκυρους χαρακτήρες όπως κενά.
     *
     * @param scheme Το σχήμα του URL (π.χ., "http", "https").
     * @param host Το όνομα κεντρικού υπολογιστή του URL.
     * @param path Η διαδρομή του URL (π.χ., "/api/data").
     * @return Το περιεχόμενο που ανακτήθηκε από το URL ως συμβολοσειρά.
     * @throws IllegalArgumentException Εάν το σχήμα, ο κεντρικός υπολογιστής ή η διαδρομή είναι null ή κενό,
     *                                  ή εάν ο κεντρικός υπολογιστής περιέχει μη έγκυρους χαρακτήρες.
     * @throws MalformedURLException Εάν το κατασκευασμένο URL δεν είναι έγκυρο.
     * @throws IOException Εάν προκύψει σφάλμα κατά την ανάγνωση από το URL.
     * @throws UnknownHostException Εάν ο κεντρικός υπολογιστής δεν μπορεί να επιλυθεί.
     */
    public String retrieveContentFromValidatedUrl(String scheme, String host, String path)
            throws IllegalArgumentException, MalformedURLException, IOException, UnknownHostException {
        if (scheme == null || scheme.trim().isEmpty()) {
            throw new IllegalArgumentException("Scheme cannot be null or empty.");
        }
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }
        if (path == null) {
            path = ""; // Allow empty path
        }

        // Validate and sanitize host for invalid characters like spaces
        String sanitizedHost = host.trim();
        if (sanitizedHost.contains(" ")) {
