                commandTemplate = "evince \"%s\""; // Exemple pour PDF
                break;
            default:
                System.err.println("Type MIME non supporté: " + mimeType);
                return;
        }

        String finalCommand = String.format(commandTemplate, filePath);

        System.out.println("Exécution de la commande: " + finalCommand);

        ProcessBuilder processBuilder;
        // Pour des commandes simples, on peut utiliser Runtime.exec(String),
        // mais ProcessBuilder est plus robuste, surtout avec des arguments.
