     * @throws IllegalArgumentException If the expression contains dangerous keywords or is invalid.
     * @throws ScriptException If there's an error during script evaluation.
     */
    public Object evaluateExpression(String expression) throws ScriptException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("Expression cannot be null or empty.");
        }

        String lowerCaseExpression = expression.toLowerCase();

        // Check for dangerous keywords
        for (String keyword : DANGEROUS_KEYWORDS) {
            if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("Expression contains a forbidden keyword: " + keyword);
            }
        }

        // Additional simple validation to limit to basic arithmetic operators and numbers
        // This regular expression allows numbers, basic operators (+, -, *, /, %), parentheses, and whitespace.
        // It specifically excludes other characters like letters, underscores, etc., preventing complex function calls.
        if (!expression.matches("^[\\d\\s\\.\\+\\-\\*/%()]+$")) {
