                "1 + java.lang.Math.PI", // Dangerous
                "var x = 10; x * 2;", // Dangerous
                "Math.sqrt(9)", // Dangerous (blocked by DANGEROUS_KEYWORDS)
                "console.log('hello')", // Dangerous
