import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    /**
     * Analyseert en evalueert een wiskundige uitdrukking van de gebruiker.
     * 
     * De functie beperkt de uitdrukking tot basisrekenkunde door
     * veelvoorkomende gevaarlijke trefwoorden te blokkeren.
     *
     * @param expression De wiskundige uitdrukking die geëvalueerd moet worden.
     * @return Het resultaat van de evaluatie als een Object (bijv. Double, Long).
     * @throws IllegalArgumentException Als de uitdrukking gevaarlijke trefwoorden bevat.
     * @throws ScriptException Als de uitdrukking syntactisch incorrect is of niet geëvalueerd kan worden.
     */
    public Object evaluateExpression(String expression) throws ScriptException {
        // Lijst van trefwoorden die niet toegestaan zijn om potentiële beveiligingsrisico's te vermijden
        Set<String> dangerousKeywords = new HashSet<>(Arrays.asList(
            "java", "import", "class", "package", "new", "this",
            "process", "runtime", "exec", "file", "system",
            "var", "function", "for", "while", "do", "if", "else",
            "switch", "case", "try", "catch", "throw", "finally",
            "const", "let", "debugger", "eval", "prototype",
            "window", "document", "console" // Specifiek voor JavaScript contexten
        ));

        // Controleer op gevaarlijke trefwoorden
        String lowerCaseExpression = expression.toLowerCase();
        for (String keyword : dangerousKeywords) {
            if (lowerCaseExpression.contains(keyword)) {
                throw new IllegalArgumentException("De uitdrukking bevat een niet toegestaan trefwoord: '" + keyword + "'");
            }
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Of "nashorn" voor JDK 8 t/m 14

        if (engine == null) {
            throw new IllegalStateException("JavaScript ScriptEngine is niet gevonden. Zorg ervoor dat de JDK correct is geïnstalleerd en geconfigureerd.");
        }

        try {
            // Evalueer de uitdrukking
            Object result = engine.eval(expression);

            // Optioneel: converteer resultaat naar een specifiek numeriek type als dat gewenst is
            if (result instanceof Number) {
                return result;
            } else if (result != null) {
                // Als het resultaat geen nummer is, maar de evaluatie is geslaagd,
                // kan het zijn dat de uitdrukking geen numeriek resultaat oplevert.
                // Bijvoorbeeld: "1==1" -> true
                // Dit kan naar eigen inzicht worden afgehandeld. Voor nu, retourneer het als Object.
                return result;
            } else {
                // Bijvoorbeeld, als de uitdrukking een lege string of een uitdrukking zonder waarde was.
                throw new ScriptException("De uitdrukking leverde geen geldig resultaat op.");
            }
        } catch (ScriptException e) {
            // Vang syntaxfouten of runtimefouten van de script-engine
            throw new ScriptException("Fout bij het evalueren van de uitdrukking: " + e.getMessage());
        } catch (Exception e) {
            // Vang andere onverwachte fouten
            throw new ScriptException("Een onverwachte fout is opgetreden: " + e.getMessage());
        }
    }

    // Optioneel: main-methode om de functionaliteit te testen
    public static void main(String[] args) {
        ClassX analyzer = new ClassX();

        String[] expressionsToTest = {
            "2 + 2 * 3",
            "(10 - 5) / 2",
            "Math.pow(2, 3) + 1", // Voorbeelden met Math functies zijn toegestaan door JavaScript engine
            "100 / 0", // Delen door nul in JS resulteert in Infinity
            "1 + 'a'", // JavaScript specifieke gedragingen
            "console.log('hello')", // Gevaarlijk, zou geblokkeerd moeten worden
            "java.lang.System.exit(0)", // Gevaarlijk, zou geblokkeerd moeten worden
            "2 * (1 + 1", // Syntactische fout
            "2 + undefined", // JavaScript undefined
            "1==1" // Boolean resultaat
        };

        for (String expr : expressionsToTest) {
            System.out.println("Uitdrukking: \"" + expr + "\"");
            try {
                Object result = analyzer.evaluateExpression(expr);
                System.out.println("  Resultaat: " + result + " (Type: " + (result != null ? result.getClass().getName() : "null") + ")");
            } catch (IllegalArgumentException e) {
                System.err.println("  Fout (veiligheid): " + e.getMessage());
            } catch (ScriptException e) {
                System.err.println("  Fout (evaluatie): " + e.getMessage());
            } catch (Exception e) {
                System.err.println("  Onverwachte fout: " + e.getMessage());
            }
            System.out.println("--------------------");
        }
    }
}
