import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Analyseert en evalueert een wiskundige uitdrukking van de gebruiker.
     * 
     * De functie beperkt de uitdrukking tot basisrekenkunde door
     * veelvoorkomende gevaarlijke trefwoorden te blokkeren.
     * 
     * @param expression De wiskundige uitdrukking als een String.
     * @return Het resultaat van de evaluatie van de uitdrukking.
     * @throws IllegalArgumentException Als de uitdrukking een geblokkeerd trefwoord bevat of als deze leeg is.
     * @throws ScriptException Als er een fout optreedt tijdens het evalueren van de uitdrukking.
     */
    public Object evaluateMathematicalExpression(String expression) throws IllegalArgumentException, ScriptException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("De uitdrukking mag niet leeg zijn.");
        }

        String lowerCaseExpression = expression.toLowerCase();

        // Lijst van geblokkeerde trefwoorden om potentiële beveiligingsproblemen te voorkomen
        String[] blockedKeywords = {
            "system", "runtime", "exec", "file", "io", "class", "java", " " + "import", "eval",
            "process", "thread", "net", "url", "socket", "reflect", "scriptengine", "manager",
            "javax", "com.sun", "sun.misc", "native", "function", "var", "let", "const",
            "while", "for", "if", "else", "switch", "try", "catch", "throw", "new", "this",
            "window", "document", "console", "prototype", "constructor", "alert", "prompt",
            "confirm", "setTimeout", "setInterval", "require", "module", "exports"
        };

        for (String keyword : blockedKeywords) {
            // Controleer of het trefwoord voorkomt, rekening houdend met woordgrenzen voor betere precisie
            // Dit is een simpele benadering; voor robuuste parsing zou een ANTLR-achtige aanpak beter zijn.
            if (lowerCaseExpression.contains(keyword)) {
                // Speciale behandeling voor "sin", "cos", "tan", "log", "sqrt", "pow"
                // Als ze in een lijst van toegestane functies staan, blokkeer ze dan niet.
                // Voor nu blokkeren we ze als ze expliciet in de lijst staan en er geen whitelist is.
                // In een echte scenario zou je een whitelist van functies hebben, niet alleen een blacklist van keywords.
                boolean isAllowedFunction = false; // Stel dit in op true als je functies zoals sin() wilt toestaan
                String[] allowedFunctions = {"math.sin", "math.cos", "math.tan", "math.log", "math.sqrt", "math.pow"};

                for (String allowedFunc : allowedFunctions) {
                    if (lowerCaseExpression.contains(allowedFunc)) {
                        isAllowedFunction = true;
                        break;
                    }
                }

                if (!isAllowedFunction || !keyword.contains("math.")) { // Blokkeer keyword tenzij het een toegestane math functie is
                     throw new IllegalArgumentException("De uitdrukking bevat een geblokkeerd trefwoord: " + keyword);
                }
            }
        }

        // Extra validatie: beperk tot tekens die typisch in wiskundige uitdrukkingen voorkomen
        // Dit helpt ook om onverwachte injecties te voorkomen.
        // Alleen cijfers, operatoren (+-*/^%), haakjes en komma's/punten (voor decimalen) zijn toegestaan.
        // Let op: Dit regex blokkeert woorden zoals "Math.PI", dus je moet dit zorgvuldig beheren.
        // Voor een eenvoudige rekenmachine, alleen cijfers en basisoperatoren.
        if (!expression.matches("[0-9+\\-*/%().\\s]+")) {
