            // Als de intentie is om Math.PI of Math.E toe te staan, dan moet dit regex worden uitgebreid.
            // Laten we aannemen dat we "Math." als prefix voor constanten/functies toestaan.
            // Dit regex is een compromis voor basisrekenkunde met mogelijke Math.*.
            if (!expression.matches("[0-9+\\-*/%().,\\sMmaAthhIiPpEe]+")) { // Allow M, a, t, h, ., P, I, E for Math.PI, Math.E
                 // We moeten preciezer zijn: als de expressie 'Math' bevat, dan alleen 'Math.PI' of 'Math.E' of 'Math.pow' etc.
                 // Dit is een oversimplificatie en kan false positives hebben.
                 // Een echte parser is hier wenselijk.
                 if (!expression.contains("Math.") && !expression.matches("[0-9+\\-*/%().,\\s]+")) {
