     * @throws IllegalArgumentException אם הביטוי מכיל תווים או מילות מפתח אסורים, או אם הביטוי ריק/null.
     * @throws ScriptException           אם מנוע הסקריפט נתקל בשגיאה בעת הערכת הביטוי.
     */
    public String evaluateArithmeticExpression(String expression) throws ScriptException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("הביטוי לא יכול להיות ריק או null.");
        }

        String cleanedExpression = expression.trim();

        // 1. הגבלת תווים מותרים: מספרים, אופרטורים בסיסיים, סוגריים, רווחים ועשרוני.
        // מאפשר גם את 'pi' ו 'e' אם יש צורך בהם בהמשך, כרגע הם לא מוערכים כקבועים.
        if (!Pattern.matches("^[0-9+\\-*/().\\s]+$", cleanedExpression)) {
            throw new IllegalArgumentException("הביטוי מכיל תווים אסורים. מותרים רק ספרות, אופרטורים בסיסיים (+-*/), סוגריים ונקודה עשרונית.");
        }

        // 2. חסימת מילות מפתח "מסוכנות" או פונקציות לא רצויות
        String[] forbiddenKeywords = {
            "java", "script", "import", "eval", "exec", "function", "class", "new", "this",
            "prototype", "window", "document", "process", "require", "console", "alert",
            "setTimeout", "setInterval", "while", "for", "if", "else", "switch", "try",
            "catch", "throw", "return", "var", "let", "const", "System", "Runtime",
            "File", "URL", "Socket", "Bridge", "load", "read", "write", "print", "exit"
        };

        String lowerCaseExpression = cleanedExpression.toLowerCase();
        for (String keyword : forbiddenKeywords) {
            if (lowerCaseExpression.contains(keyword)) {
                throw new IllegalArgumentException("הביטוי מכיל מילת מפתח אסורה: " + keyword);
            }
        }

        // 3. מניעת ניסיונות הזרקת קוד: בדיקה בסיסית של סוגריים לא מאוזנים או רצפים חשודים
        // (הערה: ScriptEngine אמור לטפל ברוב המקרים של תחביר שגוי, אבל זה שכבת הגנה נוספת)
        if (countOccurrences(cleanedExpression, '(') != countOccurrences(cleanedExpression, ')')) {
            throw new IllegalArgumentException("סוגריים לא מאוזנים בביטוי.");
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // ניתן גם להשתמש ב- "nashorn" או "graal.js" ב- JDK חדשים יותר

        if (engine == null) {
            throw new IllegalStateException("לא ניתן למצוא מנוע JavaScript. ודא ש- JDK מותקן כהלכה.");
        }

        Object result = engine.eval(cleanedExpression);

        return String.valueOf(result);
    }

    /**
     * פונקציית עזר לספירת מופעים של תו בתוך מחרוזת.
     *
     * @param text המחרוזת לחיפוש.
     * @param targetChar התו לספור.
     * @return מספר המופעים של התו.
     */
    private int countOccurrences(String text, char targetChar) {
        int count = 0;
        for (char c : text.toCharArray()) {
            if (c == targetChar) {
                count++;
            }
        }
        return count;
    }

    // דוגמה לשימוש (ניתן להסיר בפרודקשן אם אין צורך)
    public static void main(String[] args) {
