        // ביטויים תקינים
        System.out.println("2+2 = " + runEvaluation(evaluator, "2+2"));
        System.out.println(" (5 * (3 + 1)) - 2 = " + runEvaluation(evaluator, " (5 * (3 + 1)) - 2"));
        System.out.println("10 / 3 = " + runEvaluation(evaluator, "10 / 3"));
        System.out.println("10.5 + 2.3 * 4 = " + runEvaluation(evaluator, "10.5 + 2.3 * 4"));
        System.out.println("(1 + 2) * (3 + 4) = " + runEvaluation(evaluator, "(1 + 2) * (3 + 4)"));

        // ביטויים אסורים
        System.out.println("1 + java.lang.Runtime = " + runEvaluation(evaluator, "1 + java.lang.Runtime"));
        System.out.println("2 + eval('3*3') = " + runEvaluation(evaluator, "2 + eval('3*3')"));
        System.out.println("3 + alert(1) = " + runEvaluation(evaluator, "3 + alert(1)"));
        System.out.println("System.exit(0) = " + runEvaluation(evaluator, "System.exit(0)"));
        System.out.println("1 + 2; console.log(3) = " + runEvaluation(evaluator, "1 + 2; console.log(3)")); // תו לא חוקי
        System.out.println("function(){return 1} = " + runEvaluation(evaluator, "function(){return 1}"));
        System.out.println("1 + var x = 5; x + 2 = " + runEvaluation(evaluator, "1 + var x = 5; x + 2")); // תו לא חוקי
        System.out.println("1 + 2 + (3 = " + runEvaluation(evaluator, "1 + 2 + (3")); // סוגריים לא מאוזנים
        System.out.println(" = " + runEvaluation(evaluator, " ")); // ביטוי ריק
        System.out.println("null = " + runEvaluation(evaluator, null)); // ביטוי null
        System.out.println("1 % 2 = " + runEvaluation(evaluator, "1 % 2")); // תו לא חוקי
    }

    private static String runEvaluation(ClassX evaluator, String expression) {
        try {
            return evaluator.evaluateArithmeticExpression(expression);
        } catch (IllegalArgumentException | ScriptException | IllegalStateException e) {
            return "שגיאה: " + e.getMessage();
        }
    }
