import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Jäsentää ja arvioi käyttäjän antaman matemaattisen lausekkeen.
     * 
     * Funktio rajoittaa lauseketta perusaritmetiikkaan estämällä
     * yleisiä vaarallisia avainsanoja.
     */
    public Object evaluateMathematicalExpression(String expression) throws Exception {
        // Luodaan ScriptEngineManager
        ScriptEngineManager manager = new ScriptEngineManager();
        // Haetaan JavaScript-moottori
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Luettelo vaarallisista tai ei-toivotuista avainsanoista
        String[] dangerousKeywords = {
            "java", "script", "import", "class", "function", "var", "let", "const", "new",
            "while", "for", "if", "else", "switch", "try", "catch", "finally", "throw",
            "eval", "debugger", "process", "require", "console", "window", "document",
            "global", "this", "alert", "prompt", " "
        };

        // Tarkistetaan lauseke vaarallisten avainsanojen varalta
        for (String keyword : dangerousKeywords) {
            if (expression.toLowerCase().contains(keyword)) {
                throw new IllegalArgumentException("Lauseke sisältää kiellettyjä avainsanoja tai merkkejä.");
            }
        }

        // Tarkistetaan, että lauseke sisältää vain numeroita, perusoperaattoreita ja sulkuja
        // Sallitut merkit: 0-9, +, -, *, /, %, (, )
        if (!expression.matches("[0-9+\\-*/%().]+")) {
             throw new IllegalArgumentException("Lauseke sisältää kiellettyjä merkkejä.");
        }


        try {
            // Arvioidaan lauseke ja palautetaan tulos
            return engine.eval(expression);
        } catch (javax.script.ScriptException e) {
            // Käsitellään skriptivirheet
            throw new Exception("Lausekkeen arvioinnissa tapahtui virhe: " + e.getMessage(), e);
        } catch (Exception e) {
            // Käsitellään muut mahdolliset virheet
            throw new Exception("Yleinen virhe lausekkeen arvioinnissa: " + e.getMessage(), e);
        }
    }

    public static void main(String[] args) {
        ClassX calculator = new ClassX();

        // Esimerkkejä käytöstä
        String[] expressions = {
            "10 + 5 * 2",         // Odotettu: 20.0
            "(10 + 5) * 2",       // Odotettu: 30.0
            "10 / 2 + 3",         // Odotettu: 8.0
            "10 % 3",             // Odotettu: 1.0
            "1 + 2 - 3 * 4 / 2",  // Odotettu: -3.0
            "2^3",                // Odotettu: virhe (ei tueta suoraan JS-evalissa, jos ei ole Math.pow)
            "Math.pow(2,3)",      // Odotettu: virhe (sisältää kiellettyjä avainsanoja)
            "console.log('hello')", // Odotettu: virhe (sisältää kiellettyjä avainsanoja)
            "10 + java",          // Odotettu: virhe (sisältää kiellettyjä avainsanoja)
            "10 + 5 ; process.exit(1)", // Odotettu: virhe (sisältää kiellettyjä avainsanoja ja ;)
            "10 + 5 + x",           // Odotettu: virhe (sisältää kiellettyjä merkkejä 'x')
            "10 + 5 +."             // Odotettu: virhe (syntaksivirhe)
        };

        for (String expr : expressions) {
            System.out.print("Lauseke: \"" + expr + "\" -> ");
