import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Jäsentää ja arvioi käyttäjän antaman matemaattisen lausekkeen.
     * 
     * Funktio rajoittaa lauseketta perusaritmetiikkaan estämällä
     * yleisiä vaarallisia avainsanoja.
     *
     * @param expression Käyttäjän antama matemaattinen lauseke merkkijonona.
     * @return Lausekkeen arvioitu tulos double-muodossa.
     * @throws IllegalArgumentException Jos lauseke sisältää vaarallisia avainsanoja tai on tyhjä/null.
     * @throws ScriptException Jos lauseketta ei voida jäsentää tai arvioida.
     */
    public double evaluateMathExpression(String expression) throws ScriptException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("Expression cannot be null or empty.");
        }

        // Lista vaarallisista avainsanoista, jotka estetään.
        // Tämä on perustason suojaus, ei täysin kattava.
        String[] forbiddenKeywords = {
            "System", "Runtime", "Process", "File", "Class", "Thread", "java.", "javax.",
            "import", "new", "execute", "eval", "call", "load", "var", "function", "lambda",
            "while", "for", "if", "switch", "try", "catch", "throw", "return",
            "break", "continue", "exit", "quit", "debugger",
            "delete", "undefined", "null", "NaN", "Infinity",
            ";", "//", "/*", "*/", "--", "++", // Yrittää estää kommentteja ja joitain operaattoreita
            "\\", "&", "|", "^", "~", "!", "?", ":" // Yrittää estää joitakin bittioperaattoreita ja ternary-operaattoria
        };

        String lowerCaseExpression = expression.toLowerCase();
        for (String keyword : forbiddenKeywords) {
            if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("Expression contains forbidden keyword: " + keyword);
            }
        }

        // Estetään myös sulut, jotka eivät ole tasapainossa, mikä voi viitata monimutkaisempiin rakenteisiin
        // Tämän voi myös poistaa, jos halutaan tukea monimutkaisempia sisäkkäisiä lausekkeita.
        // Perusaritmetiikkaan kuuluvat usein sulut, joten tämä voi olla liian rajoittava.
        // Alla oleva tarkistus on yksinkertainen sulkujen tasapainon tarkistus.
        int openParentheses = 0;
        int closeParentheses = 0;
        for (char c : expression.toCharArray()) {
            if (c == '(') {
                openParentheses++;
            } else if (c == ')') {
                closeParentheses++;
            }
        }
        if (openParentheses != closeParentheses) {
            throw new IllegalArgumentException("Mismatched parentheses detected in the expression.");
        }


        // Yritetään suorittaa vain perusaritmetiikkaa sisältäviä lausekkeita
        // Tämä sallii numerot, desimaalit, perusoperaattorit (+, -, *, /) ja sulut.
        // Tämä regex on tarkoitettu sallimaan vain hyväksyttyjä merkkejä.
        // Huomaa, että tämä EI estä kaikkia mahdollisia vaarallisia lausekkeita,
        // mutta pyrkii rajoittamaan merkistön perusaritmetiikkaan.
        if (!expression.matches("^[0-9+\\-*/\\.\\s\\(\\)]+$")) {
            throw new IllegalArgumentException("Expression contains invalid characters. Only numbers, basic arithmetic operators (+-*/), decimal points, and parentheses are allowed.");
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Tai "nashorn" vanhemmille JDK:ille

        // Tärkeää: Arviointimenetelmä on potentiaalisesti vaarallinen
        // yllä olevat tarkistukset pyrkivät lieventämään riskiä,
        // mutta eivät ole täysin aukottomia.
        Object result = engine.eval(expression);

        // Varmista, että tulos on numeerinen
        if (result instanceof Number) {
            return ((Number) result).doubleValue();
        } else {
            throw new ScriptException("Expression evaluation did not result in a number. Result type: " + result.getClass().getName());
        }
    }

    public static void main(String[] args) {
        ClassX calculator = new ClassX();

        // Esimerkkejä
        String[] expressions = {
            "1 + 2 * 3",
            "(10 - 5) / 2",
            "1.5 + 2.7",
            "20 / 3",
            "3 * (4 + 5) - 6",
            "  10  +   20  ", // välilyönnit
            "Math.sqrt(9)", // Vaarallinen, pitäisi estää
            "System.exit(0)", // Vaarallinen, pitäisi estää
            "1 + 2; System.out.println('Hello')", // Vaarallinen, pitäisi estää
            "", // Tyhjä
            null, // Null
            "1 + (2", // Epätasapainoiset sulut
            "1 & 2" // Estetty merkki
        };

        for (String expr : expressions) {
            System.out.print("Evaluating \"" + expr + "\": ");
            try {
                double result = calculator.evaluateMathExpression(expr);
                System.out.println("Result = " + result);
            } catch (IllegalArgumentException e) {
                System.out.println("Error (IllegalArgument): " + e.getMessage());
            } catch (ScriptException e) {
                System.out.println("Error (ScriptException): " + e.getMessage());
            } catch (Exception e) {
                System.out.println("Error (Generic): " + e.getMessage());
            }
        }
    }
}
