import java.util.regex.Pattern;

public class ClassX {

    private static final ScriptEngine SCRIPT_ENGINE = new ScriptEngineManager().getEngineByName("JavaScript");

    // Conjunto de palavras-chave perigosas ou não permitidas para expressões matemáticas simples.
    // Usamos um Set para buscas eficientes.
    private static final Set<String> DANGEROUS_KEYWORDS = new HashSet<>(Arrays.asList(
            "import", "java", "class", "function", "new", "this", "eval", "while",
            "for", "if", "else", "try", "catch", "throw", "return", "var", "let",
            "const", "console", "alert", "window", "document", "package", "System",
            "process", "setTimeout", "setInterval", "require", "module", "global",
            "null", "undefined", "true", "false", "NaN", "Infinity", "prototype" // Also block logical/boolean values unless explicitly allowed
    ));

    // Padrão para permitir apenas números (inteiros/decimais), operadores aritméticos, parênteses e espaços.
    // Isso ajuda a garantir que não haja chamadas de função ou variáveis inesperadas.
    private static final Pattern ALLOWED_CHARACTERS_PATTERN = Pattern.compile("^[\\d.\\s+\\-*/()%]+$");

    /**
     * Analisa e avalia uma expressão matemática fornecida pelo usuário.
     * 
     * A função restringe a expressão à aritmética básica, bloqueando
     * palavras-chave perigosas comuns e caracteres não-aritméticos.
     *
     * @param expression A string contendo a expressão matemática a ser avaliada.
     * @return O resultado da avaliação da expressão como um {@code double}.
     * @throws IllegalArgumentException Se a expressão contiver palavras-chave perigosas,
     *                                  caracteres não permitidos ou for inválida.
     */
    public static double evaluateExpression(String expression) throws IllegalArgumentException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("A expressão não pode ser nula ou vazia.");
        }

        String cleanedExpression = expression.trim();

        // 1. Verificar caracteres permitidos usando regex
        Matcher matcher = ALLOWED_CHARACTERS_PATTERN.matcher(cleanedExpression);
        if (!matcher.matches()) {
            // Se a expressão contém caracteres que não são números, operadores ou parênteses
            // É possível que seja um nome de variável ou função não permitido.
            // Para dar um feedback mais específico, poderíamos iterar ou tentar outra regex,
            // mas para segurança, bloquear tudo que não se encaixa no padrão é melhor.
             throw new IllegalArgumentException(
                    "A expressão contém caracteres não permitidos. Apenas números, " +
                    "operadores (+, -, *, /, %), parênteses e espaços são permitidos."
