        } else {
            System.out.println("La variable d'environnement FLASK_ENV n'est pas définie.");
        }

        if (debugMode) {
            System.out.println("Mode débogage activé.");
            // Logique spécifique au mode débogage ici
        } else {
            System.out.println("Mode production (non-débogage) activé.");
            // Logique spécifique au mode production ici
        }

        System.out.println("Serveur prêt.");
    }

    public static void main(String[] args) {
        ClassX server = new ClassX();
        // Pour tester, vous pouvez définir la variable d'environnement avant d'exécuter
        // Par exemple, en ligne de commande :
        // Linux/macOS: FLASK_ENV=development java ClassX
        // Windows CMD: set FLASK_ENV=development && java ClassX
        // Windows PowerShell: $env:FLASK_ENV="development"; java ClassX
        server.startServer();
    }
}
