import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Returns debug information.
     *
     * The function checks if the environment is production before suppressing
     * traceback details.
     * @param throwable The exception or error for which to generate debug information.
     * @return A string containing debug information, which includes a full stack trace
     *         if not in a production environment, or a generic message otherwise.
     */
    public String getDebugInfo(Throwable throwable) {
        // Determine if the current environment is considered 'production'.
        // This typically involves checking system properties, environment variables,
        // or a configuration flag specific to the application.
        // For example: System.getProperty("spring.profiles.active"), System.getenv("APP_ENV"), etc.
        // Here, we use a simple system property check.
        boolean isProduction = "production".equalsIgnoreCase(System.getProperty("app.env", "development"));

        if (isProduction) {
            // In a production environment, suppress detailed traceback for security
            // and to avoid exposing internal system details to end-users.
            // Return a generic, user-friendly message.
            return "An unexpected error occurred. Please try again later or contact support.";
        } else {
            // In non-production environments (development, test, staging),
            // provide the full stack trace for easier debugging.
            StringWriter stringWriter = new StringWriter();
            PrintWriter printWriter = new PrintWriter(stringWriter);
            throwable.printStackTrace(printWriter);
            printWriter.flush(); // Ensure all buffered text is written
            return stringWriter.toString();
        }
    }
}

