     * @param throwable The Throwable object to extract debug information from.
     * @param isProduction A boolean flag indicating if the current environment is production.
     * @return A string containing debug information, with or without traceback details based on the isProduction flag.
     */
    public static String getDebugInfo(Throwable throwable, boolean isProduction) {
        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);

        if (throwable == null) {
            return "No throwable provided.";
        }

        // Always print the throwable message
        pw.println("Error Message: " + throwable.getMessage());

        // Print stack trace only if not in production
        if (!isProduction) {
            pw.println("--- Stack Trace ---");
            throwable.printStackTrace(pw);
        } else {
            pw.println("--- Stack trace suppressed in production environment ---");
        }

        pw.flush();
        return sw.toString();
    }

