     * Determines if the current application environment is production.
     * This implementation checks a system property named "APP_ENV".
     *
     * @return true if the environment is considered production, false otherwise.
     */
    private static boolean isProductionEnvironment() {
        String env = System.getProperty("APP_ENV", "dev").toLowerCase();
        return "prod".equals(env) || "production".equals(env);
    }

