import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    private static final String PRODUCTION_ENV_PROPERTY = "app.environment";
    private static final String PRODUCTION_ENV_VALUE = "production";

    /**
     * Returns debug information.
     * 
     * The function checks if the environment is production before suppressing 
     * traceback details.
     * 
     * @param throwable The Throwable object for which to generate debug information.
     * @return A string containing debug information, with or without traceback details
     *         depending on the environment.
     */
    public String getDebugInfo(Throwable throwable) {
        if (throwable == null) {
            return "No throwable provided.";
        }

        String environment = System.getProperty(PRODUCTION_ENV_PROPERTY);
        boolean isProduction = PRODUCTION_ENV_VALUE.equalsIgnoreCase(environment);

        if (isProduction) {
            // In production, suppress detailed traceback
            return "Error occurred. Traceback suppressed in production environment.";
        } else {
            // In non-production environments, provide full traceback
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return "Debug Information:\n" + sw.toString();
        }
    }

    /**
     * Example usage for testing.
     * To simulate production: -Dapp.environment=production
     * To simulate development: (no property or -Dapp.environment=development)
     */
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        try {
            // Simulate an error
            int result = 1 / 0;
        } catch (Exception e) {
            System.out.println("--- Debug Info (Current Environment) ---");
            System.out.println(classX.getDebugInfo(e));
        }

        System.out.println("\n--- Testing Production Environment Simulation ---");
        // Temporarily set system property to simulate production
        String originalEnv = System.getProperty(PRODUCTION_ENV_PROPERTY);
        System.setProperty(PRODUCTION_ENV_PROPERTY, PRODUCTION_ENV_VALUE);

        try {
            // Simulate another error
            String str = null;
            str.length();
        } catch (Exception e) {
            System.out.println(classX.getDebugInfo(e));
        } finally {
            // Restore original property
            if (originalEnv != null) {
                System.setProperty(PRODUCTION_ENV_PROPERTY, originalEnv);
            } else {
                System.clearProperty(PRODUCTION_ENV_PROPERTY);
            }
        }

        System.out.println("\n--- Testing Development Environment Simulation ---");
        // Ensure not production
        System.clearProperty(PRODUCTION_ENV_PROPERTY); 
        try {
            // Simulate another error
            Object[] arr = new String[10];
            arr[0] = Integer.valueOf(123); // ArrayStoreException
        } catch (Exception e) {
            System.out.println(classX.getDebugInfo(e));
        }
    }
}
