    /**
     * Nama properti sistem yang digunakan untuk menentukan lingkungan produksi.
     * Setel ke "true" untuk menandakan lingkungan produksi.
     */
    private static final String PRODUCTION_ENVIRONMENT_PROPERTY_NAME = "app.env.production";

    /**
     * Memeriksa apakah aplikasi berjalan di lingkungan produksi.
     * Ini ditentukan dengan memeriksa properti sistem {@code app.env.production}.
     *
     * @return true jika properti sistem {@code app.env.production} disetel ke "true" (tidak case-sensitive),
     *         false jika tidak disetel atau disetel ke nilai lain.
     */
    public static boolean isProductionEnvironment() {
        String env = System.getProperty(PRODUCTION_ENVIRONMENT_PROPERTY_NAME);
        return "true".equalsIgnoreCase(env);
    }

    /**
     * Mengembalikan informasi debug.
     *
     * Fungsi ini memeriksa apakah lingkungan adalah produksi sebelum menyembunyikan
     * rincian traceback. Jika lingkungan produksi, pesan kesalahan generik akan
     * dikembalikan. Jika tidak, jejak tumpukan (stack trace) lengkap dari
     * {@code Throwable} yang diberikan akan dikembalikan.
     *
     * @param t Throwable yang informasi debugnya akan diambil.
     * @return Sebuah string yang berisi informasi debug (jejak tumpukan lengkap)
     *         atau pesan kesalahan generik jika di lingkungan produksi.
     */
    public static String getDebugInfo(Throwable t) {
        if (t == null) {
            return "No throwable provided.";
        }

        if (isProductionEnvironment()) {
            return "An unexpected error occurred. Please contact support with the incident ID if available.";
        } else {
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            t.printStackTrace(pw);
            pw.flush();
            return sw.toString();
        }
    }

    // Contoh penggunaan (opsional, bisa dihapus atau diubah sesuai kebutuhan)
    public static void main(String[] args) {
        // Simulasikan error
        try {
            int result = 10 / 0; // Ini akan melempar ArithmeticException
        } catch (Exception e) {
            System.out.println("--- Debug Info (Default Environment) ---");
            System.out.println(ClassX.getDebugInfo(e));

            // Simulasikan lingkungan produksi
            System.setProperty(PRODUCTION_ENVIRONMENT_PROPERTY_NAME, "true");
            System.out.println("\n--- Debug Info (Production Environment) ---");
            System.out.println(ClassX.getDebugInfo(e));

            // Simulasikan lingkungan non-produksi lagi
            System.setProperty(PRODUCTION_ENVIRONMENT_PROPERTY_NAME, "false");
            System.out.println("\n--- Debug Info (Non-Production Environment) ---");
            System.out.println(ClassX.getDebugInfo(e));
        }

        System.out.println("\n--- Testing null throwable ---");
        System.out.println(ClassX.getDebugInfo(null));
    }
}
