import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    /**
     * Determines if the application is running in a production environment.
     * This flag is set once when the class is loaded.
     * It checks the system property "app.environment" or the environment variable "APP_ENVIRONMENT".
     * If either is "production" (case-insensitive), it's considered production.
     */
    private static final boolean IS_PRODUCTION;

    static {
        String environment = System.getProperty("app.environment");
        if (environment == null) {
            environment = System.getenv("APP_ENVIRONMENT");
        }
        IS_PRODUCTION = "production".equalsIgnoreCase(environment);
    }

    /**
     * Hata ayıklama bilgilerini döndürür.
     * 
     * Fonksiyon, traceback detaylarını bastırmadan önce ortamın üretim olup olmadığını kontrol eder.
     * Eğer ortam üretim ise, genel bir hata mesajı döndürülür. Aksi takdirde, tam yığın izi (stack trace) döndürülür.
     *
     * @param throwable Hata ayıklama bilgileri alınacak olan {@link Throwable} nesnesi.
     * @return Hata ayıklama bilgilerini içeren bir {@link String}. Ortam üretim ise genel bir mesaj, değilse tam yığın izi.
     */
    public static String getDebugInformation(Throwable throwable) {
        if (IS_PRODUCTION) {
            // In a production environment, return a generic error message
            // to avoid exposing sensitive internal details.
            return "An unexpected error occurred. Please contact support. Error Type: " + throwable.getClass().getSimpleName();
        } else {
            // In a non-production environment (e.g., development, testing),
            // return the full stack trace for detailed debugging.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }
}
