import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Devuelve información de depuración.
     * 
     * La función verifica si el entorno es de producción antes de suprimir los detalles del seguimiento.
     *
     * @param throwable La excepción o error para el cual se generará la información de depuración.
     * @return Una cadena que contiene información de depuración. Si el entorno es de producción,
     *         se suprime el seguimiento de la pila para evitar exponer detalles internos y se devuelve
     *         un mensaje genérico con un ID de referencia.
     */
    public String getDebugInfo(Throwable throwable) {
        // Una forma común de determinar si el entorno es de producción es mediante una propiedad del sistema
        // o una variable de entorno. Por ejemplo, "app.environment".
        boolean isProduction = "production".equalsIgnoreCase(System.getProperty("app.environment"));

        if (isProduction) {
            // En producción, devolvemos un mensaje de error genérico para evitar exponer detalles internos
            // que podrían ser un riesgo de seguridad o información confidencial del sistema.
            // En un sistema real, el error completo se registraría internamente y se devolvería un ID
            // para que el soporte pueda encontrar el error específico en los registros.
            String errorId = generateSimpleErrorId(throwable);
            return "Ocurrió un error inesperado. Por favor, contacte a soporte. ID de referencia: " + errorId;
        } else {
            // En entornos de desarrollo o pruebas, se devuelve el seguimiento de la pila completo
            // para facilitar la depuración.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            pw.flush();
            return sw.toString();
        }
    }

    /**
     * Genera un identificador simple para un error.
     * En una aplicación real, este ID podría ser un UUID, un hash más robusto,
     * o un ID de un sistema de registro centralizado.
     *
     * @param throwable La excepción para la cual generar un ID.
     * @return Un String que representa un ID de error simple.
     */
    private String generateSimpleErrorId(Throwable throwable) {
        // Para este ejemplo, usamos el hash de la excepción como un ID simple.
        // Esto NO es único ni robusto para un sistema de producción real.
        return String.format("%08X", throwable.hashCode());
    }
}
