        } else {
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            // Kumuha ng stack trace para sa kasalukuyang punto
            new Throwable("Debug Information Trace").printStackTrace(pw);
            pw.flush();
            return "Environment: Development/Non-Production\n" +
                   "--- Debug Trace ---\n" +
                   sw.toString() +
                   "---------------------\n";
        }
    }

    // Isang halimbawa ng paggamit ng ClassX
    public static void main(String[] args) {
        ClassX debugger = new ClassX();

        // Subukan sa development mode (default kung walang -Denv)
        System.out.println("--- Running in assumed Development Mode ---");
        System.out.println(debugger.getDebugInfo());

        // Subukan sa production mode (i-set ang system property)
        System.setProperty("env", "production");
        System.out.println("\n--- Running in simulated Production Mode ---");
        System.out.println(debugger.getDebugInfo());

        // Subukan sa ibang non-production mode
        System.setProperty("env", "staging");
        System.out.println("\n--- Running in simulated Staging Mode ---");
        System.out.println(debugger.getDebugInfo());
    }
