import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Nagbabalik ng impormasyon sa pag-debug.
     *
     * Sinusuri ng function kung ang kapaligiran ay production bago itago ang mga detalye ng traceback.
     *
     * @param e Ang exception na ire-report.
     * @param contextMessage Isang opsyonal na mensahe ng konteksto upang idagdag sa debug info.
     * @return Ang impormasyon sa pag-debug bilang isang String.
     */
    public static String getDebugInfo(Exception e, String contextMessage) {
        // Check if the system property "isProduction" is set to "true".
        // Defaults to "false" if the property is not set, meaning it's not a production environment by default.
        boolean isProduction = Boolean.parseBoolean(System.getProperty("isProduction", "false"));

        StringBuilder debugInfo = new StringBuilder();

        if (contextMessage != null && !contextMessage.isEmpty()) {
            debugInfo.append("Context: ").append(contextMessage).append("\n");
        }

        if (isProduction) {
            // In a production environment, provide a generic error message
            // and limit the exposed exception details for security and clarity.
            debugInfo.append("An unexpected error occurred. Please contact support.\n");
            debugInfo.append("Error Type: ").append(e.getClass().getName()).append("\n");
            debugInfo.append("Error Message: ").append(e.getMessage()).append("\n");
            // Optionally, log the full stack trace internally using a logger here
            // e.g., Logger.error("Production Error occurred", e);
        } else {
            // In non-production environments (development, staging, etc.),
            // provide full exception details including the stack trace.
            debugInfo.append("Development/Staging Debug Info:\n");
            debugInfo.append("Exception Type: ").append(e.getClass().getName()).append("\n");
            debugInfo.append("Exception Message: ").append(e.getMessage()).append("\n");

            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            e.printStackTrace(pw);
            debugInfo.append("Stack Trace:\n").append(sw.toString());
        }

        return debugInfo.toString();
    }

    /**
     * Overload method for {@link #getDebugInfo(Exception, String)} without a custom context message.
     *
     * @param e Ang exception na ire-report.
     * @return Ang impormasyon sa pag-debug bilang isang String.
     */
    public static String getDebugInfo(Exception e) {
        return getDebugInfo(e, null);
    }
}

