public class ClassX {

    /**
     * Een statische constante die aangeeft of de applicatie in een productieomgeving draait.
     * Deze waarde kan worden ingesteld via een systeemparameter, bijvoorbeeld:
     * -Dapp.environment.production=true bij het starten van de JVM.
     * Standaard is deze 'false' (niet-productie).
     */
    private static final boolean IS_PRODUCTION_ENVIRONMENT =
            Boolean.parseBoolean(System.getProperty("app.environment.production", "false"));

    /**
     * Geeft debug-informatie terug.
     *
     * De functie controleert of de omgeving productie is voordat de traceback-details worden onderdrukt.
     * In een productieomgeving wordt een vereenvoudigde foutmelding teruggegeven om te voorkomen
     * dat gevoelige details van de applicatie worden blootgesteld. In een niet-productieomgeving
     * wordt de volledige stacktrace geretourneerd.
     *
     * @param throwable De Throwable (Exception, Error, etc.) waarvoor debug-informatie nodig is.
     * @return Een String met debug-informatie. Dit kan een volledige stacktrace zijn of een vereenvoudigde boodschap.
     */
    public String getDebugInformation(Throwable throwable) {
        if (IS_PRODUCTION_ENVIRONMENT) {
            // In een productieomgeving geven we een algemene foutmelding terug
            // om gevoelige interne details te verbergen en de gebruiker niet te verwarren.
            return "Er is een onverwachte fout opgetreden. Foutcode: " + throwable.getClass().getSimpleName();
        } else {
            // In een niet-productieomgeving (bijv. ontwikkeling, test) geven we de volledige stacktrace
            // terug om debugging te vergemakkelijken.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            pw.flush(); // Zorg ervoor dat alle gegevens naar de StringWriter zijn geschreven
            return sw.toString();
        }
    }
