            return "No exception object provided for debugging.";
        }

        if (isProductionEnvironment()) {
            // In a production environment, we suppress detailed stack traces
            // to avoid exposing sensitive system information and for cleaner logs.
            return "An internal system error occurred. Please contact support. Error message: " + t.getMessage();
