import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    // A flag to determine if the current environment is production.
    // In a real application, this would typically be configured via environment variables,
    // system properties, or a dedicated configuration service.
    // Set to 'true' to simulate a production environment (suppress detailed stack traces).
    // Set to 'false' to simulate a development or non-production environment (show full stack traces).
    private static final boolean IS_PRODUCTION_ENVIRONMENT = true;

    /**
     * 返回调试信息。
     * 
     * 该函数在抑制回溯细节之前检查环境是否为生产环境。
     *
     * @param throwable 捕获到的异常或错误对象，用于生成调试信息。
     * @return 包含调试信息的字符串。如果当前环境被认为是生产环境
     *         ({@code IS_PRODUCTION_ENVIRONMENT} 为 true)，则返回一个通用的、简短的错误消息；
     *         否则（非生产环境），返回完整的堆栈跟踪信息。
     */
    public static String getDebugInfo(Throwable throwable) {
        if (throwable == null) {
            return "No throwable provided for debug information.";
        }

        if (IS_PRODUCTION_ENVIRONMENT) {
            // In a production environment, provide a generic message to prevent
            // sensitive internal details or system paths from being exposed to end-users.
            // It's recommended to log the full stack trace internally for debugging purposes.
            return "An unexpected error occurred. Please contact support. Error type: " + throwable.getClass().getSimpleName();
        } else {
            // In a non-production environment (e.g., development, staging),
            // provide the full stack trace for easier debugging by developers.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }
}
