public class ClassX {
    /**
     * Sanitizes user input by removing script tags.
     * 
     * The function uses string replacement to strip out <script> tags.
     * This implementation performs case-insensitive removal of literal "<script>"
     * and "</script>" tags, but preserves any content that was originally
     * between these tags.
     *
     * @param input The raw user input string.
     * @return The sanitized string with script tags removed.
     */
    public String sanitize(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        String sanitizedInput = input;

        // Remove opening <script> tags, case-insensitive
        sanitizedInput = sanitizedInput.replaceAll("(?i)<script>", "");

        // Remove closing </script> tags, case-insensitive
        sanitizedInput = sanitizedInput.replaceAll("(?i)</script>", "");

        return sanitizedInput;
    }
}
