public class ClassX {
    /**
     * Cleans user input by removing script tags.
     * <p>
     * This function uses string replacement to remove &lt;script&gt; tags and their content.
     * The matching is case-insensitive and removes all attributes as well as content between the tags.
     *
     * @param input The user input string to be cleaned.
