     * 通过移除脚本标签来清理用户输入。
     *
     * 该函数使用字符串替换来去除 &lt;script&gt; 标签及其内容。
     * 匹配是大小写不敏感的，并且会移除所有属性以及标签之间的内容。
     *
     * @param input 待清理的用户输入字符串。
     * @return 清理后的字符串，移除了所有脚本标签。
     */
    public String cleanScriptTags(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // Regular expression to match <script...>...</script> tags and their content.
        // (?i) enables case-insensitive matching for "script".
        // (?s) enables DOTALL mode, allowing '.' to match newline characters.
        // <script\\b[^>]*> matches the opening <script> tag with any attributes.
        // .*? matches any character (non-greedy) including newlines.
        // </script> matches the closing </script> tag.
        String cleanedInput = input.replaceAll("(?i)(?s)<script\\b[^>]*>.*?</script>", "");

        return cleanedInput;
    }
}
