import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Очищает пользовательский ввод, удаляя теги <script>.
     * 
     * Функция использует замену строк для удаления тегов <script>.
     *
     * @param input Строка, которая может содержать теги <script>.
     * @return Очищенная строка без тегов <script> и их содержимого.
     */
    public String cleanInput(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // Регулярное выражение для поиска тегов <script> и их содержимого.
        // (?i) - делает поиск нечувствительным к регистру (case-insensitive)
        // <script\\b[^>]*> - ищет открывающий тег <script> (слово `script` не часть другого слова),
        //                     допускает любые атрибуты внутри тега
        // .*? - нежадный поиск любых символов (включая символы новой строки благодаря Pattern.DOTALL)
        //       до первого совпадения закрывающего тега
        // </script> - ищет закрывающий тег </script>
        Pattern scriptPattern = Pattern.compile("<script\\b[^>]*>.*?</script>", 
                                                  Pattern.CASE_INSENSITIVE | Pattern.DOTALL);

        // Заменяем все найденные совпадения пустой строкой
        return scriptPattern.matcher(input).replaceAll("");
    }
}
