public class ClassX {
    /**
     * Bereinigt Benutzereingaben, indem Skript-Tags entfernt werden.
     * 
     * Die Funktion verwendet String-Ersetzung, um <script>-Tags zu entfernen.
     * Sie berücksichtigt verschiedene Formen von Skript-Tags (z.B. Groß-/Kleinschreibung,
     * mit und ohne Attribute) und deren Inhalt.
     *
     * @param userInput Die zu bereinigende Benutzereingabe.
     * @return Die bereinigte Zeichenkette ohne Skript-Tags.
     */
    public String cleanUserInput(String userInput) {
        if (userInput == null || userInput.isEmpty()) {
            return userInput;
        }

        // Regex, um <script>-Tags (case-insensitiv) und deren gesamten Inhalt zu entfernen.
        // (?i)        : Macht den gesamten Regex case-insensitiv.
        // <script[^>]*>: Matcht das öffnende <script>-Tag mit optionalen Attributen.
        // .*?         : Matcht nicht-gierig beliebige Zeichen zwischen dem öffnenden
        //               und schließenden Tag.
        // </script>   : Matcht das schließende </script>-Tag.
        String cleanedString = userInput.replaceAll("(?i)<script[^>]*>.*?</script>", "");

        // Zusätzlich entfernen wir potenzielle einzelne, nicht geschlossene öffnende
        // oder schließende <script>-Tags, die nicht vom vorherigen Regex erfasst wurden.
        // Dies fängt Fälle ab, in denen z.B. nur "<script>" oder nur "</script>" eingegeben wurde.
        cleanedString = cleanedString.replaceAll("(?i)<script[^>]*>", "");
        cleanedString = cleanedString.replaceAll("(?i)</script>", "");

        return cleanedString;
    }
}
