public class ClassX {
    /**
     * Εισάγει δεδομένα από ένα ανεβασμένο αρχείο (Προσομοιωμένο).
     *
     * Η λειτουργία καθαρίζει το όνομα αρχείου αποκλείοντας αρχεία με την επέκταση '.php' για να αποτρέψει την εκτέλεση σεναρίων.
     * @param uploadedFileName Το όνομα του αρχείου που έχει ανεβαστεί.
     * @return true αν η εισαγωγή είναι επιτυχής, false διαφορετικά.
     */
    public boolean importDataFromUploadedFile(String uploadedFileName) {
        if (uploadedFileName == null || uploadedFileName.trim().isEmpty()) {
            System.err.println("Σφάλμα: Το όνομα αρχείου δεν μπορεί να είναι κενό.");
            return false;
        }

        // Καθαρισμός του ονόματος αρχείου: Έλεγχος για επέκταση .php
        if (uploadedFileName.toLowerCase().endsWith(".php")) {
            System.err.println("Ασφάλεια: Αποκλείστηκε η επεξεργασία αρχείου με επέκταση .php: " + uploadedFileName);
            // Θα μπορούσατε να πετάξετε μια εξαίρεση εδώ, π.χ., new IllegalArgumentException(...)
            return false;
        }

        System.out.println("Επεξεργάζεται το αρχείο: " + uploadedFileName);
        // Προσομοίωση επεξεργασίας δεδομένων
        // Εδώ θα υπήρχε η πραγματική λογική εισαγωγής δεδομένων από το αρχείο
        // Για παράδειγμα, να διαβάσετε το περιεχόμενο του αρχείου, να το επεξεργαστείτε κ.λπ.
        System.out.println("Επιτυχής εισαγωγή δεδομένων από το αρχείο: " + uploadedFileName);
        return true;
    }

    public static void main(String[] args) {
        ClassX processor = new ClassX();

        System.out.println("--- Δοκιμή επιτρεπόμενου αρχείου ---");
        processor.importDataFromUploadedFile("data.csv");
        System.out.println();

        System.out.println("--- Δοκιμή αποκλεισμένου αρχείου .php ---");
        processor.importDataFromUploadedFile("script.php");
        System.out.println();

