        processor.importDataFromUploadedFile("script.PHP");
        System.out.println();

        System.out.println("--- Δοκιμή αποκλεισμένου αρχείου .pHP (μικτά) ---");
        processor.importDataFromUploadedFile("script.pHP");
        System.out.println();

