        // Initialize the SSLContext with our custom TrustManager.
        // The first parameter is KeyManager (can be null if not providing client certificates)
        // The second parameter is TrustManager (our custom one)
        // The third parameter is SecureRandom (can be null to use default)
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

        // Set the custom HostnameVerifier
        HostnameVerifier defaultHostnameVerifier = HttpsURLConnection.getDefaultHostnameVerifier();
        Pattern pattern = Pattern.compile(internalSubdomainPattern);

        HttpsURLConnection.setDefaultHostnameVerifier(new HostnameVerifier() {
            @Override
            public boolean verify(String hostname, SSLSession session) {
                // Check if the hostname matches an internal subdomain pattern
                if (pattern.matcher(hostname).matches()) {
                    // For internal subdomains, we still want to ensure the session is established,
                    // but the certificate check itself is bypassed by trustAllCerts.
                    // Returning true here essentially trusts the connection if it reaches this point.
                    // A more robust implementation might still check specific internal CA if available.
                    System.out.println("Hostname verification skipped for internal subdomain: " + hostname);
                    return true; // Trust internal subdomains without standard hostname verification (as per req for testing)
                } else {
                    // For external domains, use the default hostname verifier
                    System.out.println("Using default hostname verification for: " + hostname);
                    return defaultHostnameVerifier.verify(hostname, session);
                }
            }
        });

        return sslContext;
    }

