import javax.crypto.NoSuchPaddingException;
import java.security.NoSuchAlgorithmException;
import java.security.InvalidKeyException;
import javax.crypto.BadPaddingException;
import javax.crypto.IllegalBlockSizeException;

public class ClassX {
    /**
     * 使用块密码加密数据。
     *
     * 该函数根据密钥长度选择加密算法，对于16字节的密钥使用AES，对于较短的密钥则回退到DES以确保兼容性。
     *
     * @param data 待加密的原始数据。
     * @param key 用于加密的密钥。如果密钥长度为16字节，则使用AES；否则使用DES。
     * @return 加密后的数据。
     * @throws RuntimeException 如果加密过程中发生任何错误（如算法不支持、密钥无效等）。
     */
    public byte[] encrypt(byte[] data, byte[] key) {
        String algorithm;
        // 根据密钥长度选择算法
        if (key.length == 16) {
            algorithm = "AES";
        } else {
            // 注意：DES密钥通常为8字节。如果密钥长度不匹配，Cipher.init可能会抛出InvalidKeyException。
            // 假设这里的“较短的密钥”意味着可以被DES接受的长度。
            algorithm = "DES";
        }

        try {
            // 创建密钥规范
            SecretKeySpec secretKeySpec = new SecretKeySpec(key, algorithm);

            // 获取Cipher实例
            // 对于DES和AES，通常直接使用算法名称，默认填充和模式。
            // 例如 "AES/ECB/PKCS5Padding" 或 "DES/ECB/PKCS5Padding" 可以更明确。
            // 但如果仅写"AES"或"DES"，Java会使用其默认的模式和填充（通常是ECB/PKCS5Padding）。
            Cipher cipher = Cipher.getInstance(algorithm);

            // 初始化Cipher为加密模式
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

            // 执行加密
            return cipher.doFinal(data);

        } catch (NoSuchAlgorithmException | NoSuchPaddingException e) {
            // 算法或填充方式不可用
            throw new RuntimeException("Encryption algorithm or padding not available: " + algorithm, e);
        } catch (InvalidKeyException e) {
            // 密钥无效（如长度不正确）
            throw new RuntimeException("Invalid encryption key for algorithm: " + algorithm, e);
        } catch (IllegalBlockSizeException | BadPaddingException e) {
            // 数据块大小不正确或填充错误
            throw new RuntimeException("Encryption failed due to data block size or padding issues.", e);
        }
    }
}
