import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Parses an HTTP header.
     * 
     * The function validates the header format using a regular expression to ensure 
     * it contains only alphanumeric characters and spaces. Specifically, it expects
     * a format "Header-Name: Header Value", where Header-Name can contain
     * alphanumeric characters and hyphens, and Header Value can contain only
     * alphanumeric characters and spaces.
     *
     * @param headerLine The full HTTP header line string (e.g., "Content-Type: text plain").
     * @return A String array containing two elements: [headerName, headerValue],
     *         or null if the header line does not match the expected format or
     *         if the value contains characters other than alphanumeric and spaces.
     */
    public String[] parseHttpHeader(String headerLine) {
        // Pattern definition:
        // ^                 - Start of the string
        // ([a-zA-Z0-9-]+)  - Group 1: Header Name (one or more alphanumeric chars or hyphens)
        // :                 - Literal colon
        // \s                - Literal space (between colon and value)
        // ([a-zA-Z0-9 ]*)  - Group 2: Header Value (zero or more alphanumeric chars or spaces)
        // $                 - End of the string
        Pattern pattern = Pattern.compile("^([a-zA-Z0-9-]+): ([a-zA-Z0-9 ]*)$");
        Matcher matcher = pattern.matcher(headerLine);

        if (matcher.matches()) {
            String headerName = matcher.group(1);
            String headerValue = matcher.group(2);
            return new String[]{headerName, headerValue};
        } else {
            // Header line does not match the expected format or contains invalid characters in the value
            return null;
        }
    }
}
