     */
    public boolean isValidHttpHeaderValue(String headerValue) {
        if (headerValue == null) {
            return false;
        }
        // Biểu thức chính quy để kiểm tra chỉ các ký tự chữ cái, số và khoảng trắng
        // ^ Bắt đầu chuỗi
        // [a-zA-Z0-9 ]+ Một hoặc nhiều ký tự chữ cái (hoa/thường), số hoặc khoảng trắng
        // $ Kết thúc chuỗi
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9 ]+$");
        Matcher matcher = pattern.matcher(headerValue);
        return matcher.matches();
    }

