        // Các trường hợp thử nghiệm
        String validHeader1 = "Content Type text html";
        String validHeader2 = "Cache Control no-cache";
        String validHeader3 = "User Agent MyApp/1.0 (Windows NT 10.0)"; // Note: this regex would fail here due to parentheses and slashes
                                                                       // Re-reading: "chỉ chứa các ký tự chữ cái, số và khoảng trắng"
                                                                       // My regex `^[a-zA-Z0-9 ]+$` correctly implements this.
                                                                       // So, 'User Agent MyApp/1.0 (Windows NT 10.0)' should be INVALID.

        String invalidHeader1 = "Content-Type: text/html"; // Chứa dấu gạch ngang và dấu hai chấm
