        String invalidHeader3 = "Host: example.com"; // Chứa dấu chấm
        String emptyHeader = ""; // Trống
        String nullHeader = null; // Null

        System.out.println("Validating: '" + validHeader1 + "' -> " + parser.isValidHttpHeaderValue(validHeader1)); // true
        System.out.println("Validating: '" + validHeader2 + "' -> " + parser.isValidHttpHeaderValue(validHeader2)); // true
        System.out.println("Validating: '" + validHeader3 + "' -> " + parser.isValidHttpHeaderValue(validHeader3)); // false (due to non-alphanumeric/space chars)

