import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * 解析HTTP头。
     *
     * 该函数使用正则表达式验证头的格式，以确保它仅包含字母数字字符和空格。
     * 预期格式为 "Key: Value"，其中Key和Value都只包含字母数字字符和空格。
     *
     * @param headerLine 待解析的HTTP头字符串，例如 "Content Type: Text Plain"
     * @return 包含[Key, Value]的字符串数组，如果格式不匹配则返回null。
     * @throws IllegalArgumentException 如果输入的headerLine为null。
     */
    public String[] parseHeader(String headerLine) {
        if (headerLine == null) {
            throw new IllegalArgumentException("Header line cannot be null.");
        }

        // 正则表达式匹配 Key: Value 格式。
        // Key: 至少一个字母数字字符或空格。
        // Value: 至少一个字母数字字符或空格。
        // 允许冒号后有零个或多个空格。
        // ^ 和 $ 确保匹配整个字符串。
        String regex = "^([a-zA-Z0-9 ]+):\\s*([a-zA-Z0-9 ]+)$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(headerLine);

        if (matcher.matches()) {
            String key = matcher.group(1).trim(); // 获取Key，并去除两端空格
            String value = matcher.group(2).trim(); // 获取Value，并去除两端空格
            return new String[]{key, value};
        } else {
            return null; // 格式不匹配
        }
    }
}
