import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {

    // Precompile the pattern for efficiency, as it will be used multiple times.
    // The pattern ensures the string contains only alphanumeric characters (a-z, A-Z, 0-9) and spaces.
    // The anchors ^ and $ ensure that the entire string must match the pattern.
    private static final Pattern HTTP_HEADER_VALIDATION_PATTERN =
            Pattern.compile("^[a-zA-Z0-9 ]+$");

    /**
     * Analizza un'intestazione HTTP.
     * 
     * La funzione convalida il formato dell'intestazione utilizzando un'espressione regolare per garantire che contenga solo caratteri alfanumerici e spazi.
