     * @param header La stringa dell'intestazione HTTP da analizzare e convalidare.
     * @return true se l'intestazione è valida (contiene solo caratteri alfanumerici e spazi), false altrimenti.
     */
    public static boolean isValidHttpHeader(String header) {
        // A null or empty header string is considered invalid.
        if (header == null || header.isEmpty()) {
            return false;
        }

        // Use the precompiled pattern to match the entire header string.
        Matcher matcher = HTTP_HEADER_VALIDATION_PATTERN.matcher(header);
        return matcher.matches();
    }
}
