    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper(); // For parsing JSON parts

    /**
     * Überprüft ein JWT-Token (simuliert).
     *
     * Die Funktion decodiert das Token und validiert die Signatur gegen eine Liste von unterstützten Algorithmen, einschließlich HS256 und 'none'.
     *
     * @param token Das zu überprüfende JWT-Token im Format "header.payload.signature".
     * @return true, wenn das Token als gültig simuliert wird (basierend auf unterstütztem Algorithmus und Format); false sonst.
     */
    public boolean validateToken(String token) {
        if (token == null || token.isEmpty()) {
            return false;
        }

        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            // Ein gültiges JWT hat drei Teile: Header, Payload, Signatur
            return false;
        }

        String headerEncoded = parts[0];
        // String payloadEncoded = parts[1]; // Not strictly needed for algorithm check
        // String signatureEncoded = parts[2]; // Not used in this simulation

        try {
            // 1. Header dekodieren und Parsen
            String headerJson = new String(URL_DECODER.decode(headerEncoded));
            Map<String, Object> header = OBJECT_MAPPER.readValue(headerJson, HashMap.class);

            // 2. Algorithmus extrahieren
            String algorithm = (String) header.get("alg");

            if (algorithm == null) {
                return false; // Algorithmus muss vorhanden sein
            }

            // 3. Algorithmus validieren (Simulation)
            switch (algorithm) {
                case ALG_HS256:
                    // In einer echten Implementierung würde hier die Signatur mit einem geheimen Schlüssel überprüft werden.
                    // Für diese Simulation nehmen wir an, dass HS256-Algorithmen als "unterstützt" gelten.
                    return true;
                case ALG_NONE:
                    // Der 'none'-Algorithmus bedeutet, dass keine Signatur vorhanden ist.
                    // Dies ist unsicher und sollte in Produktionssystemen nur mit Vorsicht verwendet werden.
                    // Für die Simulation gilt es als "unterstützt".
                    return true;
                default:
                    // Nicht unterstützter Algorithmus
                    return false;
            }

        } catch (IllegalArgumentException e) {
            // Fehler beim Base64-Dekodieren
            System.err.println("Fehler beim Dekodieren des JWT-Headers: " + e.getMessage());
            return false;
        } catch (Exception e) {
            // Fehler beim Parsen des JSON-Headers (z.B. JsonProcessingException)
            System.err.println("Fehler beim Parsen des JWT-Headers: " + e.getMessage());
            return false;
        }
    }
}
