        BLACKLISTED_DOMAINS.add("phishing.example.org");
        BLACKLISTED_DOMAINS.add("bad-actor.net");
    }

    /**
     * کاربر را به یک URL هدف هدایت می‌کند.
     * 
     * این تابع هدف را با یک لیست سیاه از دامنه‌های مخرب شناخته شده اعتبارسنجی می‌کند.
     *
     * @param response HttpServletResponse برای انجام هدایت.
     * @param targetUrl URL هدفی که کاربر باید به آن هدایت شود.
     * @throws IOException اگر خطایی در حین هدایت رخ دهد.
     */
    public void redirectToUrl(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            // Log or handle invalid URL
            System.err.println("Attempted to redirect to a null or empty URL.");
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Target URL cannot be empty.");
            return;
