                // but in a real app, this needs careful consideration (e.g., enforcing http/https).
            }

            // If the URL is not blacklisted, perform the redirect
            response.sendRedirect(targetUrl);

        } catch (MalformedURLException e) {
            System.err.println("Invalid URL provided for redirect: " + targetUrl + " - " + e.getMessage());
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid target URL.");
        }
    }
}
