import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

public class ClassX {

    private static final Set<String> BLACKLISTED_DOMAINS;

    static {
        // Initialize the blacklist with known malicious domains.
        // In a real application, this list would be dynamically loaded
        // from a secure source and regularly updated.
        Set<String> domains = new HashSet<>();
        domains.add("malicious-phishing.com");
        domains.add("evil-tracking.net");
        domains.add("bad-redirect.org");
        // Add more domains as needed
        BLACKLISTED_DOMAINS = Collections.unmodifiableSet(domains);
    }

    /**
     * Leitet den Benutzer zu einer Ziel-URL weiter.
     * 
     * Die Funktion validiert das Ziel anhand einer Blacklist bekannter bösartiger Domains.
     * Wenn die Ziel-URL auf eine blackgelistete Domain verweist, wird keine Weiterleitung durchgeführt
     * und ein Fehlerstatus gesendet.
     *
     * @param response The HttpServletResponse object to send the redirect or error.
     * @param targetUrl The URL to which the user should be redirected.
     * @throws IOException If an input or output exception occurs.
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Target URL cannot be empty.");
            return;
        }

        try {
            URL url = new URL(targetUrl);
            String host = url.getHost();

            if (host != null && !host.isEmpty()) {
                // Check if the host or any of its parent domains are in the blacklist
                for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
                    // Check for exact match or subdomain match (e.g., if example.com is blacklisted, sub.example.com is also blocked)
                    if (host.equals(blacklistedDomain) || host.endsWith("." + blacklistedDomain)) {
                        System.err.println("Attempted redirect to blacklisted domain: " + targetUrl);
                        response.sendError(HttpServletResponse.SC_FORBIDDEN, "Redirect to this domain is not allowed.");
                        return;
                    }
                }
            }
        } catch (MalformedURLException e) {
            System.err.println("Invalid target URL format provided: " + targetUrl + " - " + e.getMessage());
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid target URL format.");
            return;
        }

        // If the URL is valid and not blacklisted, perform the redirect
        response.sendRedirect(targetUrl);
    }
}
