import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.Set;
import java.util.HashSet;

public class ClassX {

    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        // Initialize with some example blacklisted domains
        // In a real application, this list would be loaded from a secure configuration
        // or a database and kept up-to-date.
        BLACKLISTED_DOMAINS.add("malicious.com");
        BLACKLISTED_DOMAINS.add("phishing.example.org");
        BLACKLISTED_DOMAINS.add("badactor.net");
    }

    /**
     * Redirige l'utilisateur vers une URL cible.
     *
     * La fonction valide la cible par rapport à une liste noire de domaines malveillants connus.
     *
     * @param response L'objet HttpServletResponse pour effectuer la redirection.
     * @param targetUrl L'URL vers laquelle rediriger l'utilisateur.
     * @return true si la redirection a été effectuée avec succès, false sinon (ex: URL invalide ou blacklistée).
     * @throws IOException Si une erreur d'entrée/sortie se produit lors de l'envoi de la redirection.
     */
    public boolean safeRedirect(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            // Log this attempt or handle as an error
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Target URL cannot be empty.");
            return false;
        }

        try {
            URL url = new URL(targetUrl);
            String host = url.getHost();

            if (host != null) {
                for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
                    // Check if the host directly matches or is a subdomain of a blacklisted domain
                    if (host.equalsIgnoreCase(blacklistedDomain) || host.endsWith("." + blacklistedDomain)) {
                        // Log this attempt or handle as an error
                        response.sendError(HttpServletResponse.SC_FORBIDDEN, "Redirection to a blacklisted domain is not allowed.");
                        return false;
                    }
                }
            }

            // Perform the redirection if not blacklisted
            response.sendRedirect(targetUrl);
            return true;

        } catch (MalformedURLException e) {
            // Log this attempt or handle as an error
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid target URL format.");
            return false;
        }
    }
}
