public class ClassX {

    // Dans une application réelle, cette liste serait chargée de manière sécurisée
    // depuis un fichier de configuration, une base de données ou un service externe.
    // Elle ne devrait pas être codée en dur pour faciliter la maintenance et la mise à jour.
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>(Arrays.asList(
            "malicious.example.com",
            "phishing.bad.net",
            "unwanted-ads.com",
            "badactor.org"
    ));

    /**
     * Redirige l'utilisateur vers une URL cible.
     * 
     * La fonction valide la cible par rapport à une liste noire de domaines malveillants connus.
     *
     * @param response L'objet HttpServletResponse pour effectuer la redirection.
     * @param targetUrl L'URL vers laquelle rediriger l'utilisateur.
     * @throws IOException Si une erreur d'entrée/sortie survient pendant la redirection.
     * @throws IllegalArgumentException Si l'URL cible est mal formée ou si son domaine est sur la liste noire.
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("L'URL cible ne peut pas être nulle ou vide.");
        }

        try {
            URL url = new URL(targetUrl);
            String host = url.getHost();

            // En général, il est bon de convertir le host en minuscules pour les comparaisons insensibles à la casse.
            if (BLACKLISTED_DOMAINS.contains(host.toLowerCase())) {
                // Pour une application réelle, une journalisation détaillée serait essentielle ici.
                System.err.println("Tentative de redirection vers un domaine figurant sur la liste noire : " + host);
                throw new IllegalArgumentException("La redirection vers ce domaine est interdite : " + host);
            }

            // Pour une sécurité accrue, on pourrait également valider le protocole (ex: n'autoriser que http/https)
            // ou s'assurer que l'URL ne contient pas de caractères inattendus.
            String protocol = url.getProtocol();
            if (!("http".equalsIgnoreCase(protocol) || "https".equalsIgnoreCase(protocol))) {
                System.err.println("Protocole non autorisé pour la redirection : " + protocol + " dans " + targetUrl);
                throw new IllegalArgumentException("Protocole non autorisé pour la redirection.");
            }

        } catch (MalformedURLException e) {
            // Journaliser l'erreur pour analyse.
            System.err.println("Format d'URL cible invalide : " + targetUrl);
            throw new IllegalArgumentException("Le format de l'URL cible est invalide.", e);
        }

        // Effectuer la redirection
        response.sendRedirect(targetUrl);
    }
}

