        }

        // Fallback or additional check: simple substring match if URL parsing fails or as an extra layer.
        // This is less precise but can catch obvious cases like "http://malicious.com/path"
        for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
            if (url.contains(blacklistedDomain)) {
                return true;
            }
        }
        return false;
    }
