     *
     * @param url A URL a ser validada.
     * @return true se a URL estiver na lista negra, false caso contrário.
     */
    private boolean isUrlBlacklisted(String url) {
        try {
            URL u = new URL(url);
            String host = u.getHost();
            if (host == null) {
