        if (isUrlBlacklisted(targetUrl)) {
            LOGGER.log(Level.WARNING, "Tentativa de redirecionamento para domínio na lista negra: {0}", targetUrl);
            // Poderíamos redirecionar para uma página de erro segura ou simplesmente não fazer nada
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Redirecionamento para domínio perigoso bloqueado.");
            return;
