import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.inspector.TagInspector;
import org.yaml.snakeyaml.nodes.Tag;

public class ClassX {
    /**
     * Laadt configuratie vanuit een YAML-string.
     *
     * De functie controleert op expliciete gevaarlijke tags om objectinstantiatie te voorkomen.
     *
     * @param yamlString De YAML-string die de configuratie bevat.
     * @param configClass De klasse waarnaar de configuratie moet worden gedeserialiseerd.
     * @param <T> Het type van de configuratieklasse.
     * @return Een object van het gespecificeerde type, gevuld met de configuratiegegevens.
     * @throws org.yaml.snakeyaml.error.YAMLException Als de YAML-string ongeldig is of gevaarlijke tags bevat.
     */
    public <T> T loadConfig(String yamlString, Class<T> configClass) {
        // Initialiseer de Constructor voor de specifieke configuratieklasse
        Constructor constructor = new Constructor(configClass);

        // Definieer een aangepaste TagInspector om gevaarlijke tags te weigeren
        TagInspector tagInspector = new TagInspector() {
            @Override
            public boolean isAllowed(Tag tag) {
                // Weiger de generieke !!java.object tag en andere potentieel gevaarlijke tags
                if (tag.equals(Tag.JAVA_OBJECT) ||
                    tag.startsWith("!!javax.script.ScriptEngineManager") || // Bijv. om RCE te voorkomen
                    tag.startsWith("!!java.net.URL") || // Bijv. om SSRF te voorkomen
                    tag.startsWith("!!java.nio.file.Paths") || // Potentieel gevaarlijke file I/O
                    tag.startsWith("!!java.lang.ProcessBuilder") // Potentieel gevaarlijke procesuitvoering
                    // Voeg hier andere tags toe die als gevaarlijk worden beschouwd
                ) {
                    return false; // Deze tag is niet toegestaan
                }
                // Sta alle andere tags toe. Voor SnakeYAML 2.0+ is de standaard veel veiliger.
                // Dit biedt een expliciete controlelaag, ook voor oudere versies of specifieke bedrijfscases.
                return true;
            }
        };

        // Stel de aangepaste TagInspector in voor de constructor
        constructor.setTagInspector(tagInspector);

        // Initialiseer SnakeYAML met de geconfigureerde constructor
        Yaml yaml = new Yaml(constructor);

        // Laad de configuratie vanuit de YAML-string naar het gespecificeerde klasse-object
        return yaml.loadAs(yamlString, configClass);
    }
}
