import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.error.YAMLException;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Laadt configuratie vanuit een YAML-string.
     * <p>
     * De functie controleert op expliciete gevaarlijke tags om objectinstantiatie te voorkomen.
     *
     * @param yamlString De YAML-configuratiestring.
     * @param type       Het Class-object van het type waarin de configuratie moet worden geladen.
     * @param <T>        Het generieke type van het configuratieobject.
     * @return Een object van het opgegeven type met de geladen configuratie.
     * @throws YAMLException Als de YAML-string gevaarlijke tags bevat of anderszins ongeldig is.
     */
    public <T> T loadConfigFromString(String yamlString, Class<T> type) throws YAMLException {
        // Regex om te zoeken naar expliciete YAML-tags (bijv. !!java.lang.Object)
        // We willen voorkomen dat willekeurige klassen worden geïnstantieerd.
        // Dit is een basiscontrole en kan worden uitgebreid afhankelijk van de benodigde whitelisting.
        // LET OP: !!str, !!int, !!map, etc. zijn veilige tags en worden vaak impliciet gebruikt.
        // We richten ons hier op expliciete tags die niet standaard datatypen zijn.
        Pattern dangerousTagPattern = Pattern.compile("!![^\\s\"',{}\\[\\]\\-`*&]*");

        Matcher matcher = dangerousTagPattern.matcher(yamlString);
        while (matcher.find()) {
            String tag = matcher.group();
            // Hier kunnen specifieke veilige tags worden whitelisted indien nodig.
            // Bijvoorbeeld: if (!tag.startsWith("!!map") && !tag.startsWith("!!seq") && ...)
            // Voor de meeste configuraties zijn expliciete object-instantiatie tags gevaarlijk.
            // Deze implementatie blokkeert alle expliciete tags die geen primitieven of collecties zijn,
            // wat een veiligere standaard is voor algemene configuratiebestanden.
            if (!tag.startsWith("!!str") && !tag.startsWith("!!int") && !tag.startsWith("!!float") &&
                !tag.startsWith("!!bool") && !tag.startsWith("!!null") && !tag.startsWith("!!timestamp") &&
                !tag.startsWith("!!map") && !tag.startsWith("!!seq")) {
                throw new YAMLException("Potentieel gevaarlijke YAML-tag gedetecteerd: " + tag +
                                        ". Objectinstantiatie van willekeurige klassen is niet toegestaan.");
            }
        }

        // Gebruik een expliciete constructor die alleen de opgegeven type accepteert.
        // De SafeConstructor van SnakeYAML is standaard al veilig tegen arbitraire object creatie.
        // Door een Constructor te gebruiken met het target type, dwingen we het type af.
        Yaml yaml = new Yaml(new Constructor(type));
        return yaml.load(yamlString);
    }
}
