import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor; // Import SafeConstructor for security

public class ClassX {
    /**
     * Charge la configuration à partir d'une chaîne YAML.
     * 
     * La fonction vérifie les balises dangereuses explicites pour empêcher l'instanciation d'objets.
     *
     * @param yamlContent La chaîne YAML à charger.
     * @return L'objet de configuration chargé depuis YAML. Le type exact dépend du contenu YAML.
     */
    public Object loadConfiguration(String yamlContent) {
        // Utilise SafeConstructor pour prévenir l'instanciation arbitraire d'objets
        // à partir des balises YAML. SafeConstructor restreint les types qui peuvent
        // être créés aux types basiques (String, Integer, Map, List, etc.),
        // empêchant la désérialisation d'objets Java arbitraires spécifiés via
        // des balises comme !!java.lang.Object ou similaires, qui peuvent être exploitées.
        Yaml yaml = new Yaml(new SafeConstructor());

        // Charge le contenu YAML. Le type de retour dépendra de la structure YAML.
        // Par exemple, une carte de niveau supérieur retournera une Map<String, Object>,
        // une liste retournera une List<Object>, un scalaire retournera un String/Integer, etc.
        return yaml.load(yamlContent);
    }
}

