     * Fungsi ini memeriksa tanda bahaya yang jelas untuk mengelakkan
     * penciptaan objek.
     *
     * @param <T> Tipe objek konfigurasi yang diharapkan.
     * @param yamlString Rentetan YAML yang akan dimuat.
     * @param configType Kelas target untuk memetakan YAML.
     * @return Objek konfigurasi yang dimuat dari YAML.
     */
    public <T> T loadConfig(String yamlString, Class<T> configType) {
        // Menggunakan Constructor dengan kelas root spesifik membantu mencegah
        // pembuatan objek arbitrer dengan membatasi deserialisasi ke struktur tipe yang ditentukan.
        // Ini mengurangi kerentanan deserialisasi YAML umum di mana YAML berbahaya dapat
        // membuat instance kelas arbitrer (misalnya, !!java/object:org.example.EvilClass)
        // yang bukan bagian dari skema konfigurasi yang diharapkan.
        Yaml yaml = new Yaml(new Constructor(configType));
        return yaml.load(yamlString);
    }

    /**
     * Memuat data generik dari rentetan YAML secara aman, hanya memperbolehkan tipe dasar
     * dan koleksi standar (peta, daftar).
     *
     * Ini tidak akan membuat objek Java kustom apa pun.
     *
     * @param yamlString Rentetan YAML yang akan dimuat.
     * @return Objek generik (misalnya, Map, List, String, Integer) yang dimuat dari YAML.
     */
    public Object loadSafeGenericData(String yamlString) {
        // SafeConstructor mencegah pembuatan objek Java kustom,
        // hanya mengizinkan tipe primitif, String, List, dan Map.
        Yaml yaml = new Yaml(new SafeConstructor());
        return yaml.load(yamlString);
    }
