    // Kifejezetten tiltott címkék halmaza, amelyek potenciálisan veszélyes osztályokat képviselhetnek
    private static final Set<String> DANGEROUS_TAGS = new HashSet<>();

    static {
        // Példák potenciálisan veszélyes címkékre. Ezt a listát a biztonsági követelmények alapján kell karbantartani.
        DANGEROUS_TAGS.add("tag:yaml.org,2002:java.object"); // Általános Java objektumok
        DANGEROUS_TAGS.add("!!java.lang.Object"); // specifikus java.lang.Object
        DANGEROUS_TAGS.add("!!java.util.HashSet"); // specifikus java.util.HashSet
        DANGEROUS_TAGS.add("!!javax.sql.DataSource"); // specifikus javax.sql.DataSource
        // További osztályneveket is hozzáadhatunk, amikről tudjuk, hogy rosszindulatú célokra használhatók.
        // Például:
        // DANGEROUS_TAGS.add("!!org.springframework.beans.factory.config.PropertyPathFactoryBean");
        // DANGEROUS_TAGS.add("!!com.sun.rowset.JdbcRowSetImpl");
        // stb.
    }

    /**
     * YAML karakterláncból betölti a konfigurációt.
     * <p>
     * A függvény ellenőrzi a kifejezett veszélyes címkéket, hogy megakadályozza
     * az objektum példányosítását.
     *
     * @param <T> A konfigurációs osztály típusa.
     * @param yamlString A betöltendő YAML karakterlánc.
     * @param type A konfigurációs osztály {@code Class} objektuma.
     * @return A betöltött konfigurációs objektum.
     * @throws YAMLException Ha a YAML karakterlánc nem érvényes, vagy veszélyes címkét tartalmaz.
     */
    public <T> T loadConfigFromYaml(String yamlString, Class<T> type) {
        // Egyedi konstruktor létrehozása, amely ellenőrzi a címkéket a példányosítás előtt.
        Constructor customConstructor = new Constructor(type) {
            @Override
            protected Class<?> getClassForName(String name) throws ClassNotFoundException {
                // Ellenőrizzük, hogy az osztálynév szerepel-e a tiltott listán, mielőtt betöltenénk.
                // Itt egy egyszerű string egyezés történik, ami elég lehet, de bonyolultabb logika is alkalmazható.
                if (DANGEROUS_TAGS.contains("!!" + name) || DANGEROUS_TAGS.contains(Tag.PREFIX + name)) {
                    throw new YAMLException("Attempted to load a disallowed class: " + name);
                }
                return super.getClassForName(name);
            }

            @Override
            protected Class<?> getClassForNode(org.yaml.snakeyaml.nodes.Node node) {
                // Ellenőrizzük a csomópont címkéjét.
                // A SnakeYAML egyéni címkéket is használhat, pl. "!!com.example.MyClass".
                // De a standard "tag:yaml.org,2002:java.object" is megengedheti az tetszőleges objektumok deserializációját.
                String tagValue = node.getTag().getValue();

                // Ellenőrizzük az általános Java objektum címkét, ha a felhasználó megpróbálja használni
                if (tagValue.equals(Tag.JAVA_OBJECT.getValue())) {
                     throw new YAMLException("The generic '!!java.object' tag is disallowed for security reasons.");
                }

                // Ellenőrizzük a specifikus osztálycímkéket, pl. "!!java.lang.Runtime"
                for (String dangerousTag : DANGEROUS_TAGS) {
                    if (tagValue.startsWith(dangerousTag)) { // Elkapja a "!!java.lang.Runtime" és "!!java.lang.Runtime foo"
                        throw new YAMLException("Attempted to load a disallowed tag: " + tagValue);
                    }
                }

                // Ha nem találunk tiltott címkét, akkor az alapértelmezett viselkedés.
                return super.getClassForNode(node);
            }
        };

        // Használjunk SafeConstructor-t az alapértelmezett adattípusokhoz, és felülírjuk
        // az osztálybetöltési logikát a customConstructor segítségével.
        // VAGY, ha csak az általános "tag:yaml.org,2002:java.object" címke letiltása a cél,
        // akkor egyszerűen használhatunk SafeConstructor-t, és az nem engedi a tetszőleges objektumokat.
        // De a feladat "explicit dangerous tags" (kifejezett veszélyes címkék) ellenőrzését kéri,
        // ami azt jelenti, hogy saját listánk van.
        Yaml yaml = new Yaml(customConstructor);

        try {
            return yaml.loadAs(yamlString, type);
        } catch (YAMLException e) {
            // A SnakeYAML hibákat YAMLException-ként dobja.
            // Általánosabb hibaüzenetet adhatunk, vagy továbbadhatjuk az eredetit.
            throw new YAMLException("Error loading YAML configuration: " + e.getMessage(), e);
        } catch (Exception e) {
            // Egyéb futásidejű hibák, amelyek a betöltés során előfordulhatnak.
            throw new YAMLException("An unexpected error occurred during YAML loading.", e);
        }
    }
