import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import javax.xml.XMLConstants; // For secure processing features

public class ClassX {
    /**
     * Parses an XML document.
     * 
     * The function checks for the presence of 'DOCTYPE' declarations to prevent XXE.
     * It disables DTD processing and external entity resolution.
     *
     * @param xmlString The XML document as a string.
     * @return A org.w3c.dom.Document object representing the parsed XML.
     * @throws ParserConfigurationException if a DocumentBuilder cannot be created which satisfies the configuration requested.
     * @throws SAXException if any parse errors occur.
     * @throws IOException if any IO errors occur.
     */
    public static Document parseXml(String xmlString) 
            throws ParserConfigurationException, SAXException, IOException {

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Prevent XXE attacks by disabling DTDs and external entities
        // 1. Disallow DOCTYPE declarations explicitly (most direct way to prevent DTD processing)
        try {
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (ParserConfigurationException e) {
            // This feature may not be supported by all parsers, log or handle as needed
            // If it's not supported, rely on other features below.
            // For robust security, it's safer to fail early or use a different parser.
            System.err.println("Warning: Feature 'disallow-doctype-decl' not supported. Relying on other security features. " + e.getMessage());
        }

        // 2. Disable external general entities
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // 3. Disable external parameter entities
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // 4. Disable XInclude (additional security measure)
        factory.setXIncludeAware(false);
        // 5. Do not expand entity references (can help prevent some forms of XXE)
        factory.setExpandEntityReferences(false);
        // 6. Set secure processing (a general security feature)
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // 7. Limit external schema access (relevant if schema validation is used)
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, ""); // Prevent access to external DTDs
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, ""); // Prevent access to external schemas

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parse the XML string from a ByteArrayInputStream
        try (ByteArrayInputStream input = new ByteArrayInputStream(xmlString.getBytes("UTF-8"))) {
            return builder.parse(input);
        }
    }
}
