import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Parses an XML document.
     * 
     * The function checks for the presence of 'DOCTYPE' declarations to prevent XXE.
     * It configures the DocumentBuilderFactory to disable DTDs and external entities.
     *
     * @param xmlString The XML content as a String.
     * @return A {@link Document} object representing the parsed XML.
     * @throws ParserConfigurationException If a DocumentBuilder cannot be created which satisfies the configuration requested.
     * @throws SAXException If any parse error or warning occurs.
     * @throws IOException If an I/O error occurs.
     * @throws IllegalArgumentException If the xmlString is null or empty.
     */
    public static Document parseXml(String xmlString) throws ParserConfigurationException, SAXException, IOException {
        if (xmlString == null || xmlString.trim().isEmpty()) {
            throw new IllegalArgumentException("XML string cannot be null or empty.");
        }

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Configure the factory to prevent XXE (XML External Entity) attacks.
        // These settings disable DTDs and external entity processing.
        try {
            // Disallow DOCTYPE declarations altogether, which prevents most XXE attacks.
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (ParserConfigurationException e) {
            // Some parsers might not support this feature, proceed with other measures.
            // If the feature isn't supported, explicit DOCTYPE detection or other features become more critical.
            System.err.println("Parser does not support feature 'http://apache.org/xml/features/disallow-doctype-decl'. Applying other XXE prevention measures.");
        }

        // Standard XXE prevention measures
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);

        // This ensures the parser won't attempt to retrieve external DTDs or schemas
        factory.setValidating(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parse the XML from a ByteArrayInputStream to ensure consistent encoding
        try (ByteArrayInputStream input = new ByteArrayInputStream(xmlString.getBytes(StandardCharsets.UTF_8))) {
            return builder.parse(input);
        }
    }
}

