import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;

public class ClassX {
    /**
     * Analiza un documento XML.
     * 
     * La función verifica la presencia de declaraciones 'DOCTYPE' para prevenir XXE.
     *
     * @param xmlStream El flujo de entrada que contiene el documento XML.
     * @return El objeto Document W3C que representa el XML parseado.
     * @throws ParserConfigurationException Si no se puede configurar un parser de documentos
     *         debido a un error interno o de configuración.
     * @throws SAXException Si ocurre un error durante el parseo del XML (por ejemplo, XML mal formado).
     * @throws IOException Si ocurre un error de E/S al leer del flujo.
     */
    public Document parseXmlDocument(ByteArrayInputStream xmlStream)
            throws ParserConfigurationException, SAXException, IOException {

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Configuración para prevenir XXE (XML External Entity)
        // Deshabilita el procesamiento de DOCTYPE para evitar la inclusión de entidades externas.
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Configurar un manejador de errores personalizado para evitar la carga de DTD externas
        // incluso si 'disallow-doctype-decl' no es suficiente en algunos parsers o versiones antiguas.
        builder.setEntityResolver((publicId, systemId) -> {
            if (systemId != null && systemId.endsWith(".dtd")) {
                // Si se detecta un intento de cargar un DTD externo, devolver una fuente vacía.
                // Esto efectivamente detiene la carga del DTD sin lanzar una excepción.
                return new InputSource(new ByteArrayInputStream("".getBytes()));
            }
            return null; // Usar el comportamiento predeterminado para otras entidades
        });

        return builder.parse(xmlStream);
    }
}
