import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Analiza un documento XML.
     * 
     * La función verifica la presencia de declaraciones 'DOCTYPE' para prevenir XXE.
     *
     * @param xmlString La cadena XML a analizar.
     * @return El documento DOM analizado.
     * @throws ParserConfigurationException Si ocurre un problema con la configuración del parser.
     * @throws SAXException Si ocurre un error de parsing SAX.
     * @throws IOException Si ocurre un error de E/S.
     */
    public Document parseXmlDocument(String xmlString) 
            throws ParserConfigurationException, SAXException, IOException {

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Deshabilitar el procesamiento de DTDs para prevenir XXE.
        // Esto desactiva el procesamiento de DOCTYPE completamente.
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // También es buena práctica deshabilitar entidades externas en general
        // aunque disallow-doctype-decl debería ser suficiente si no hay DTDs.
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // Desactivar XInclude, otra posible fuente de vulnerabilidades si no es necesario.
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        try (ByteArrayInputStream input = new ByteArrayInputStream(xmlString.getBytes(StandardCharsets.UTF_8))) {
            return builder.parse(new InputSource(input));
        }
    }
}
