import javax.xml.XMLConstants; // Import for XMLConstants

public class ClassX {
    /**
     * Analiza un documento XML de forma segura, previniendo ataques XXE.
     * La función deshabilita explícitamente las declaraciones 'DOCTYPE' y otras
     * funcionalidades relacionadas con entidades externas para prevenir XXE.
     *
     * @param xmlContent El contenido XML como una cadena.
     * @return Un objeto Document que representa el XML analizado.
     * @throws ParserConfigurationException Si ocurre un problema al configurar el parser.
     * @throws SAXException Si ocurre un error durante el análisis del XML.
     * @throws IOException Si ocurre un error de E/S al leer el contenido XML.
     */
    public Document parseXmlSecurely(String xmlContent) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // Deshabilitar la declaración DOCTYPE para prevenir ataques XXE
        // (JAXP 1.5+ feature)
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // También es buena práctica deshabilitar la carga de entidades externas
        // y DTDs para una protección completa contra XXE.
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

        // Configurar el cargador de DTD para ignorar DTDs externas si todavía no se ha deshabilitado
        // (JAXP 1.5+)
        // dbf.setXIncludeAware(false); // No se permite el procesamiento de XInclude
