import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Analiza un documento XML.
     * 
     * La función verifica la presencia de declaraciones 'DOCTYPE' para prevenir XXE.
     *
     * @param xmlContent La cadena XML a analizar.
     * @return El objeto Document que representa el XML analizado.
     * @throws ParserConfigurationException Si ocurre un problema de configuración del analizador.
     * @throws SAXException Si ocurre un error de análisis XML (por ejemplo, XML mal formado o DOCTYPE).
     * @throws IOException Si ocurre un error de E/S.
     */
    public Document parseXml(String xmlContent) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Prevención de XXE: Deshabilitar DOCTYPE y la resolución de entidades externas.
        // La directiva "http://apache.org/xml/features/disallow-doctype-decl" es
        // la forma más directa de prevenir la declaración DOCTYPE, lo que previene
        // la mayoría de los ataques XXE basados en DTD.
        // Si hay un DOCTYPE, se lanzará un SAXException.
        try {
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (ParserConfigurationException e) {
            // Algunos analizadores no soportan esta característica,
            // se debe intentar deshabilitar otras características relacionadas.
            // Para un manejo robusto, se pueden registrar warnings o
            // usar un enfoque más conservador con otros flags.
            // En este ejemplo, continuamos con otros flags si esta falla.
        }

