        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // Deshabilitar la resolución de entidades de parámetros externas
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // Deshabilitar XInclude
        factory.setXIncludeAware(false);
        // Deshabilitar la expansión de referencias de entidad (aunque menos crítica si las entidades externas están deshabilitadas)
        factory.setExpandEntityReferences(false);
        // Activar el procesamiento seguro, una buena práctica general
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parsear el contenido XML desde un InputStream
        try (InputStream is = new ByteArrayInputStream(xmlContent.getBytes(StandardCharsets.UTF_8))) {
            return builder.parse(is);
        }
    }
}

