import java.io.IOException;
import javax.xml.XMLConstants; // Import for XMLConstants.FEATURE_SECURE_PROCESSING

public class ClassX {
    /**
     * Analiza un documento XML de manera segura, previniendo ataques XXE.
     *
     * La función configura el DocumentBuilderFactory para deshabilitar el procesamiento
     * de DOCTYPE y la expansión de entidades externas, mitigando así el riesgo de XXE.
     *
     * @param xmlContent La cadena de texto que contiene el documento XML a analizar.
     * @return Un objeto Document que representa el árbol DOM del XML analizado.
     * @throws ParserConfigurationException Si no se puede crear un analizador XML con la configuración especificada.
     * @throws SAXException Si ocurre un error de análisis XML.
     * @throws IOException Si ocurre un error de entrada/salida durante la lectura del XML.
     */
    public Document parseXml(String xmlContent) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Configuración para prevenir ataques XXE:
        // 1. Deshabilitar el procesamiento de DOCTYPE (específico de Xerces, pero muy efectivo)
        //    Esto evita la declaración de entidades externas a través de DOCTYPE.
        try {
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (ParserConfigurationException e) {
            // Ignorar si el analizador no soporta esta característica,
            // pero es una de las principales defensas.
            System.err.println("Advertencia: El analizador XML no soporta 'disallow-doctype-decl'. " +
                               "La protección contra XXE puede ser incompleta. " + e.getMessage());
        }

        // 2. Deshabilitar la expansión de entidades generales externas
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // 3. Deshabilitar la expansión de entidades de parámetros externas
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // 4. Deshabilitar la expansión de referencias de entidad en general
        factory.setExpandEntityReferences(false);
        // 5. Habilitar el procesamiento seguro para restringir el acceso a recursos externos
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // 6. Deshabilitar XInclude
        factory.setXIncludeAware(false);
        // 7. Deshabilitar la validación si no es estrictamente necesaria
        factory.setValidating(false);


        DocumentBuilder builder = factory.newDocumentBuilder();
        ByteArrayInputStream input = new ByteArrayInputStream(xmlContent.getBytes("UTF-8"));
        return builder.parse(input);
    }
}

