import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Parst ein XML-Dokument.
     * 
     * Die Funktion überprüft das Vorhandensein von 'DOCTYPE'-Deklarationen, um XXE zu verhindern.
     *
     * @param xmlContent Der XML-Inhalt als String.
     * @return Ein {@link Document}-Objekt, das den geparsten XML-Inhalt darstellt.
     * @throws ParserConfigurationException Wenn ein Problem mit der Konfiguration des Parsers auftritt.
     * @throws SAXException Wenn ein SAX-Fehler während des Parsens auftritt.
     * @throws IOException Wenn ein E/A-Fehler während des Lesens der XML-Daten auftritt.
     */
    public Document parseXmlDocument(String xmlContent) 
            throws ParserConfigurationException, SAXException, IOException {

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Disable DTDs and external entities to prevent XXE vulnerabilities
        // https://cheatsheetseries.owasp.org/cheatsheets/XML_External_Entity_Prevention_Cheat_Sheet.html#java
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        try (InputStream is = new ByteArrayInputStream(xmlContent.getBytes(StandardCharsets.UTF_8))) {
