public class ClassX {
    /**
     * Analisa um documento XML.
     * 
     * A função verifica a presença de declarações 'DOCTYPE' para prevenir XXE.
     *
     * @param xmlString A string contendo o conteúdo XML a ser analisado.
     * @return O objeto Document resultante da análise do XML.
     * @throws ParserConfigurationException Se houver um problema na configuração do parser.
     * @throws SAXException Se ocorrer um erro durante a análise SAX do XML.
     * @throws IOException Se ocorrer um erro de I/O ao ler o XML.
     */
    public Document parseXml(String xmlString) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // Configurações para prevenir ataques XXE
        // 1. Desabilita processamento de DOCTYPE para evitar carregamento de entidades externas
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // 2. Garante o processamento seguro
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // 3. Desabilita entidades gerais e de parâmetros externas (redundante com a primeira, mas boa prática)
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // 4. Desabilita carregamento de DTDs externas (redundante com a primeira, mas boa prática)
        dbf.setXMLEntityResolver(null); // Explicitamente define para não resolver entidades externas

        // Opcional, mas recomendado para evitar referências a esquemas externos
        dbf.setExpandEntityReferences(false); 

        DocumentBuilder db = dbf.newDocumentBuilder();

        // Analisa o XML a partir de um ByteArrayInputStream
        return db.parse(new ByteArrayInputStream(xmlString.getBytes()));
    }
}

