     * @throws IllegalArgumentException Si le contenu XML est null ou vide.
     */
    public Document parseXmlSafely(String xmlContent) throws ParserConfigurationException, SAXException, IOException {
        if (xmlContent == null || xmlContent.trim().isEmpty()) {
            throw new IllegalArgumentException("XML content cannot be null or empty.");
        }

        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // **Mesures de sécurité contre les XXE (XML External Entity)**

        // 1. Désactiver le traitement des DOCTYPE declarations.
        // C'est la mesure la plus directe pour prévenir les XXE basées sur les DTD.
        // Cette fonctionnalité est souvent supportée par les implémentations JAXP.
        try {
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (ParserConfigurationException e) {
