import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Fetches content from a URL.
     * 
     * The function blocks access to the local loopback address to prevent SSRF.
     *
     * @param urlString The URL to fetch content from.
     * @return The content fetched from the URL as a String.
     * @throws IOException If an I/O error occurs, or if the URL points to a loopback address.
     * @throws MalformedURLException If the urlString is not a valid URL.
     * @throws IllegalArgumentException If the urlString is null or empty.
     */
    public String fetchUrlContent(String urlString) throws IOException, MalformedURLException, IllegalArgumentException {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new IllegalArgumentException("URL string cannot be null or empty.");
        }

        URL url = new URL(urlString);
        String host = url.getHost();

        // SSRF protection: Check if the host resolves to a loopback address
        try {
            // Resolve all IP addresses for the host
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress addr : addresses) {
                if (addr.isLoopbackAddress()) {
                    throw new IOException("Access to loopback address is blocked for security reasons: " + host);
                }
                // Optional: Also block private IP ranges if not intended for internal use
                // if (addr.isSiteLocalAddress()) {
                //     throw new IOException("Access to private network address is blocked for security reasons: " + host);
                // }
            }
