import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * 从 URL 获取内容。
     * 
     * 该函数阻止访问本地回环地址，以防止 SSRF。
     *
     * @param urlString 要获取内容的 URL 字符串。
     * @return URL 的内容作为字符串。
     * @throws IOException 如果在读取 URL 内容时发生 I/O 错误。
     * @throws IllegalArgumentException 如果 URL 指向本地回环地址。
     * @throws java.net.MalformedURLException 如果 urlString 不是有效的 URL 格式。
     */
    public static String getContentFromUrl(String urlString) throws IOException {
        URL url = new URL(urlString);

        // 获取主机名并解析其 IP 地址
        String host = url.getHost();
        if (host == null || host.isEmpty()) {
            throw new IllegalArgumentException("URL host cannot be null or empty.");
        }

        try {
            InetAddress address = InetAddress.getByName(host);

            // 检查 IP 地址是否为本地回环地址 (e.g., 127.0.0.1, ::1)
            if (address.isLoopbackAddress()) {
                throw new IllegalArgumentException("Access to loopback address is forbidden: " + host);
            }

            // （可选）如果需要更严格的SSRF保护，还可以检查内网地址
            // if (address.isSiteLocalAddress()) {
            //     throw new IllegalArgumentException("Access to private network address is forbidden: " + host);
            // }

        } catch (UnknownHostException e) {
            // 如果主机名无法解析，则抛出异常，这通常是正常的URL错误
            throw new IOException("Cannot resolve host for URL: " + host, e);
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
                content.append(System.lineSeparator()); // 保持原始的行分隔符
            }
        }
        return content.toString();
    }
}

