     */
    public String fetchUrlContent(String urlString) throws IOException, SecurityException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("A URL fornecida é inválida: " + urlString + ". Detalhes: " + e.getMessage());
