import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.URL;
import java.net.URLConnection;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Obtiene contenido de una URL.
     *
     * La función bloquea el acceso a la dirección de bucle invertido local y a redes privadas
     * para prevenir SSRF (Server-Side Request Forgery).
     *
     * @param urlString La URL de la cual obtener el contenido.
     * @return El contenido de la URL como una cadena de texto.
     * @throws IOException Si ocurre un error de E/S o si el acceso a la URL está prohibido por motivos de seguridad.
     * @throws SecurityException Si la URL apunta a una dirección de bucle invertido o a una red local/privada.
     */
    public String getContentFromUrl(String urlString) throws IOException {
        URL url = new URL(urlString);
        String host = url.getHost();

        // 1. Resolver el nombre de host para obtener todas las direcciones IP asociadas
        InetAddress[] addresses;
        try {
            addresses = InetAddress.getAllByName(host);
        } catch (UnknownHostException e) {
            throw new IOException("No se pudo resolver el nombre de host: " + host, e);
        }

        // 2. Comprobar si alguna de las direcciones IP es local/bucle invertido/privada
        for (InetAddress address : addresses) {
            if (address.isLoopbackAddress() || address.isSiteLocalAddress()) {
                throw new SecurityException("Acceso prohibido a direcciones de bucle invertido o redes privadas: " + address.getHostAddress());
            }
        }

        // 3. Establecer conexión y leer contenido
        StringBuilder content = new StringBuilder();
        URLConnection connection = url.openConnection();

        // Opcional: Establecer un timeout para la conexión y lectura
        connection.setConnectTimeout(5000); // 5 segundos
        connection.setReadTimeout(10000);   // 10 segundos

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }

        return content.toString();
    }
}

