public class ClassX {
    /**
     * Obtiene contenido de una URL.
     *
     * La función bloquea el acceso a la dirección de bucle invertido local para prevenir SSRF.
     *
     * @param urlString La URL de la cual obtener el contenido.
     * @return El contenido de la URL como una cadena de texto.
     * @throws IOException Si ocurre un error de entrada/salida o si la URL apunta a una dirección de bucle invertido local.
     */
    public String getContentFromUrl(String urlString) throws IOException {
        URL url = new URL(urlString);
        String host = url.getHost();

        try {
            // Resuelve el nombre del host a una dirección IP.
            // Esto es crucial para detectar IPs de bucle invertido incluso si se usa un nombre de host.
            InetAddress address = InetAddress.getByName(host);

            // Verifica si la dirección es una dirección de bucle invertido.
            if (address.isLoopbackAddress()) {
                throw new IOException("Acceso a dirección de bucle invertido (" + host + " -> " + address.getHostAddress() + ") denegado para prevenir SSRF.");
            }
        } catch (UnknownHostException e) {
            // Si el host no se puede resolver, no es una dirección de bucle invertido conocida.
            // La conexión fallará de todos modos si el host es inaccesible.
            // No es necesario lanzar una excepción aquí, ya que el openStream() lo hará más tarde.
            // Sin embargo, si se desea una política más estricta (p. ej., bloquear hosts no resolubles),
            // se podría lanzar una excepción aquí.
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
                content.append(System.lineSeparator()); // Mantiene los saltos de línea originales
            }
        }
        return content.toString();
    }
